(function () {
  'use strict';

  const lesson = (slug, title, summary, everyday, formula, steps, examples, mistake, tip, questions, level = 'مبتدئ', minutes = 5) => ({
    slug, title, summary, everyday, formula, steps, examples, mistake, tip, questions, level, minutes
  });

  const grammar = [
    lesson('g-subject-pronouns','ضمائر الفاعل','تعرّف على الكلمة التي تخبرنا: من الذي يفعل؟','بدل أن تكرر اسم أحمد في كل جملة، تستطيع أن تقول He. الضمير يختصر الاسم ويجعل كلامك أسهل.','Subject + verb',
      ['اسأل نفسك: من يقوم بالفعل؟ هذا هو الفاعل.','استخدم I للمتكلم، وyou للمخاطب، وhe أو she للشخص، وit لغير العاقل غالبًا.','استخدم we لمجموعة فيها المتكلم، وthey لمجموعة أخرى.'],
      [{en:'I play football.',ar:'أنا ألعب كرة القدم.',focus:'I'},{en:'Mona is kind. She helps her friends.',ar:'منى لطيفة. هي تساعد صديقاتها.',focus:'She'},{en:'The books are new. They are interesting.',ar:'الكتب جديدة. إنها ممتعة.',focus:'They'}],
      {wrong:'Ahmed is a student. Ahmed studies English.',right:'Ahmed is a student. He studies English.',why:'نستخدم He بدل تكرار اسم أحمد لأنه شخص مذكر واحد.'},
      'لا تخلط بين we وthey: استخدم we عندما تكون أنت ضمن المجموعة.',
      [{text:'___ am ready.',options:['I','He','They'],answer:0,explain:'I تعني أنا، ولذلك نقول I am.'},{text:'Sara is my sister. ___ is kind.',options:['He','She','It'],answer:1,explain:'نستخدم She عند الحديث عن Sara.'},{text:'Ali and I are friends. ___ play together.',options:['They','We','He'],answer:1,explain:'Ali and I تعني أنا وعلي؛ لذلك نستخدم We.'}]),
    lesson('g-be-verb','فعل be: am / is / are','تعلّم كيف تصف نفسك وشخصًا آخر أو مكانًا باستخدام am وis وare.','تخيّل أنك تعرّف بنفسك: أنا طالب، هي سعيدة، هم في المدرسة. هنا نحتاج فعل be لربط الشخص بوصفه أو مكانه.','Subject + am / is / are + noun / adjective / place',
      ['مع I نستخدم am.','مع he وshe وit أو اسم مفرد نستخدم is.','مع you وwe وthey أو الجمع نستخدم are.','للنفي أضف not، وللسؤال قدّم am أو is أو are إلى البداية.'],
      [{en:'I am a student.',ar:'أنا طالب.',focus:'am'},{en:'She is happy.',ar:'هي سعيدة.',focus:'is'},{en:'They are at school.',ar:'هم في المدرسة.',focus:'are'}],
      {wrong:'She happy.',right:'She is happy.',why:'الوصف يحتاج فعل be؛ لا نترك الصفة وحدها بعد الفاعل في هذه الجملة.'},
      'احفظها كإيقاع: I am — He is — They are.',
      [{text:'I ___ a student.',options:['am','is','are'],answer:0,explain:'مع I نستخدم am.'},{text:'My brother ___ tall.',options:['am','is','are'],answer:1,explain:'My brother مفرد، لذلك نستخدم is.'},{text:'The children ___ ready.',options:['am','is','are'],answer:2,explain:'children جمع، لذلك نستخدم are.'}]),
    lesson('g-present-simple','المضارع البسيط','استخدمه للعادة والروتين والحقائق التي تتكرر أو تبقى صحيحة.','تصف يومك المعتاد: أستيقظ، أذهب إلى المدرسة، وأدرس الإنجليزية. هذه عادات وليست أفعالًا تحدث الآن فقط.','I / you / we / they + base verb — he / she / it + verb-s',
      ['ابدأ بالفاعل.','مع I وyou وwe وthey استخدم الفعل الأساسي: play, study, go.','مع he وshe وit أضف غالبًا s أو es، وقد تتغير نهاية الفعل مثل study → studies.','للنفي والسؤال استخدم do أو does، ثم الفعل الأساسي دون s.'],
      [{en:'I study English every day.',ar:'أدرس الإنجليزية كل يوم.',focus:'study'},{en:'He plays football on Fridays.',ar:'هو يلعب كرة القدم أيام الجمعة.',focus:'plays'},{en:'She goes to school by bus.',ar:'هي تذهب إلى المدرسة بالحافلة.',focus:'goes'}],
      {wrong:'She go to school every day.',right:'She goes to school every day.',why:'مع she في الجملة المثبتة نضيف غالبًا s أو es إلى الفعل.'},
      'كلمات مثل usually وoften وevery day تساعدك على ملاحظة العادة، لكنها ليست شرطًا لوجود المضارع البسيط.',
      [{text:'He ___ English every day.',options:['study','studies','studying'],answer:1,explain:'مع he نضيف غالبًا s، وstudy تصبح studies.'},{text:'They ___ football on Fridays.',options:['plays','playing','play'],answer:2,explain:'مع they نستخدم الفعل الأساسي play.'},{text:'My sister ___ TV at night.',options:['watches','watch','watching'],answer:0,explain:'مع my sister وهي مفرد مؤنث نستخدم watches.'}]),
    lesson('g-present-continuous','المضارع المستمر','صف فعلًا يحدث الآن أو خلال فترة مؤقتة حول الوقت الحالي.','صديقك يسألك: ماذا تفعل الآن؟ تقول: أنا أدرس. الفعل يحدث في هذه اللحظة، لذلك نستخدم المضارع المستمر.','Subject + am / is / are + verb-ing',
      ['اختر am أو is أو are بحسب الفاعل.','أضف ing إلى الفعل: read → reading.','استخدم now أو at the moment عند الحاجة إلى توضيح أن الفعل جارٍ.','في النفي أضف not بعد am أو is أو are.'],
      [{en:'I am studying now.',ar:'أنا أدرس الآن.',focus:'am studying'},{en:'They are playing football.',ar:'هم يلعبون كرة القدم.',focus:'are playing'},{en:'She is reading a book.',ar:'هي تقرأ كتابًا.',focus:'is reading'}],
      {wrong:'I reading now.',right:'I am reading now.',why:'لا بد من فعل be قبل الفعل المنتهي بـ ing.'},
      'لا تكتفِ بإضافة ing؛ تذكّر الجزء الأول من القاعدة: am / is / are.',
      [{text:'I ___ reading now.',options:['am','is','are'],answer:0,explain:'مع I نستخدم am.'},{text:'The children are ___.',options:['play','playing','plays'],answer:1,explain:'بعد are في المضارع المستمر نستخدم verb-ing.'},{text:'She ___ studying at the moment.',options:['are','am','is'],answer:2,explain:'مع she نستخدم is.'}]),
    lesson('g-past-simple','الماضي البسيط','تحدث عن حدث وقع وانتهى في الماضي.','تحكي لصديقك ما فعلته أمس: زرت قريبًا، شاهدت فيلمًا، أو ذهبت إلى المدرسة. الحدث انتهى، لذلك نستخدم الماضي البسيط.','Subject + past verb — negative: did not + base verb',
      ['في الفعل المنتظم نضيف غالبًا ed: visit → visited.','الأفعال غير المنتظمة لها شكل خاص: go → went.','للنفي استخدم did not أو didn’t ثم الفعل الأساسي.','للسؤال ابدأ غالبًا بـ Did ثم الفاعل والفعل الأساسي.'],
      [{en:'We visited our uncle yesterday.',ar:'زرنا عمّنا أمس.',focus:'visited'},{en:'She went to school early.',ar:'ذهبت إلى المدرسة مبكرًا.',focus:'went'},{en:'I didn’t watch TV last night.',ar:'لم أشاهد التلفاز ليلة أمس.',focus:'didn’t watch'}],
      {wrong:'I didn’t went.',right:'I didn’t go.',why:'did تحمل معنى الماضي؛ لذلك يعود الفعل بعدها إلى صورته الأساسية go.'},
      'بعد did أو didn’t استخدم الفعل الأساسي دائمًا، حتى مع الأفعال غير المنتظمة.',
      [{text:'Yesterday, she ___ to the library.',options:['go','went','goes'],answer:1,explain:'حدث انتهى أمس؛ والماضي من go هو went.'},{text:'We didn’t ___ the match.',options:['watched','watch','watches'],answer:1,explain:'بعد didn’t نستخدم الفعل الأساسي watch.'},{text:'___ you visit your friend?',options:['Did','Do','Are'],answer:0,explain:'السؤال عن حدث ماضٍ يبدأ بـ Did.'}]),
    lesson('g-past-continuous','الماضي المستمر','صف فعلًا كان جاريًا في لحظة محددة في الماضي.','تخيّل أنك كنت تقرأ الساعة الثامنة مساءً، ثم اتصل بك صديق. القراءة كانت مستمرة عندما وقع الاتصال.','Subject + was / were + verb-ing',
      ['استخدم was مع I وhe وshe وit.','استخدم were مع you وwe وthey.','أضف ing إلى الفعل الأساسي.','عندما يجتمع حدث مستمر مع حدث قصير، قد نستخدم while أو when لتوضيح العلاقة.'],
      [{en:'I was reading at eight.',ar:'كنت أقرأ في الساعة الثامنة.',focus:'was reading'},{en:'They were playing when it rained.',ar:'كانوا يلعبون عندما أمطرت.',focus:'were playing'},{en:'She was sleeping while I was studying.',ar:'كانت نائمة بينما كنت أدرس.',focus:'was sleeping'}],
      {wrong:'They was playing.',right:'They were playing.',why:'مع they نستخدم were وليس was.'},
      'اسأل: هل كان الفعل مستمرًا في تلك اللحظة؟ إذا نعم، فقد يناسبه الماضي المستمر.',
      [{text:'At 9 p.m., I ___ studying.',options:['was','were','am'],answer:0,explain:'مع I في الماضي المستمر نستخدم was.'},{text:'The boys ___ playing.',options:['was','are','were'],answer:2,explain:'مع boys وهي جمع نستخدم were.'},{text:'She was ___ a book.',options:['read','reads','reading'],answer:2,explain:'بعد was في الماضي المستمر نستخدم verb-ing.'}]),
    lesson('g-future-will','المستقبل باستخدام will','تحدث عن توقع أو قرار تتخذه الآن أو وعد للمستقبل.','أحدهم يطلب مساعدتك فتقول: سأساعدك. أو تنظر إلى السماء وتتوقع المطر. يمكن أن يناسب ذلك will.','Subject + will + base verb',
      ['ضع will بعد الفاعل.','استخدم الفعل الأساسي بعدها دون s أو ed أو ing.','للنفي استخدم will not أو won’t.','للسؤال قدّم will إلى بداية الجملة.'],
      [{en:'I will help you.',ar:'سأساعدك.',focus:'will help'},{en:'Maybe it will rain tomorrow.',ar:'ربما تمطر غدًا.',focus:'will rain'},{en:'She won’t be late.',ar:'لن تتأخر.',focus:'won’t'}],
      {wrong:'He will goes.',right:'He will go.',why:'بعد will يأتي الفعل الأساسي دون s.'},
      'تذكّر أن will لا تتغير مع I أو he أو they؛ تبقى كما هي.',
      [{text:'I will ___ you tomorrow.',options:['call','calls','calling'],answer:0,explain:'بعد will نستخدم الفعل الأساسي call.'},{text:'She ___ help us.',options:['will','wills','is will'],answer:0,explain:'will واحدة مع كل الضمائر.'},{text:'Choose the correct sentence.',options:['He will goes.','He will go.','He will going.'],answer:1,explain:'بعد will نستخدم go دون s أو ing.'}]),
    lesson('g-going-to','المستقبل باستخدام going to','عبّر عن خطة أو نية، أو توقع له دليل واضح أمامك.','قررت مسبقًا أن تتعلم الإنجليزية هذا الأسبوع. هذه خطة موجودة قبل لحظة الكلام، لذلك تناسبها going to.','Subject + am / is / are + going to + base verb',
      ['اختر am أو is أو are بحسب الفاعل.','أضف going to بعد فعل be.','ضع الفعل الأساسي بعد to.','استخدمها للخطة والنية أو توقع مبني على علامة واضحة.'],
      [{en:'I am going to learn English.',ar:'سأتعلم الإنجليزية (هذه خطتي).',focus:'am going to learn'},{en:'They are going to travel next week.',ar:'سيسافرون الأسبوع القادم.',focus:'are going to travel'},{en:'Look at the clouds! It is going to rain.',ar:'انظر إلى الغيوم! يبدو أنها ستمطر.',focus:'is going to rain'}],
      {wrong:'She going to study.',right:'She is going to study.',why:'نحتاج إلى فعل be قبل going to.'},
      'لا تخلط بين going to وwill: الأولى تبرز الخطة أو الدليل، والثانية كثيرًا ما تستخدم للتوقع أو القرار اللحظي.',
      [{text:'She ___ going to study tonight.',options:['is','are','am'],answer:0,explain:'مع she نستخدم is.'},{text:'We are going to ___ early.',options:['leaves','leave','leaving'],answer:1,explain:'بعد going to يأتي الفعل الأساسي leave.'},{text:'A plan decided earlier often uses ___.',options:['going to','did','was'],answer:0,explain:'تستخدم going to كثيرًا للتعبير عن خطة أو نية.'}]),
    lesson('g-present-perfect','المضارع التام','اربط حدثًا ماضيًا بالحاضر: تجربة، نتيجة، أو فترة لم تنتهِ.','أنهيت واجبك للتو؛ المهم الآن أن الواجب أصبح جاهزًا. أو تتحدث عن تجربة زرت فيها مكانًا من قبل دون تحديد وقت منتهٍ.','Subject + have / has + past participle',
      ['استخدم have مع I وyou وwe وthey.','استخدم has مع he وshe وit.','ضع التصريف الثالث للفعل بعد have أو has.','لا تحدد عادةً وقتًا ماضيًا منتهيًا مثل yesterday مع المضارع التام.'],
      [{en:'I have finished my homework.',ar:'لقد أنهيت واجبي.',focus:'have finished'},{en:'She has visited London.',ar:'سبق لها زيارة لندن.',focus:'has visited'},{en:'We have lived here for two years.',ar:'نعيش هنا منذ سنتين.',focus:'have lived'}],
      {wrong:'She have finished.',right:'She has finished.',why:'مع she نستخدم has، ثم التصريف الثالث.'},
      'احفظ التصريف الثالث للأفعال غير المنتظمة مثل go → gone وsee → seen.',
      [{text:'I ___ finished my work.',options:['has','have','had'],answer:1,explain:'مع I نستخدم have.'},{text:'He has ___ the film.',options:['see','saw','seen'],answer:2,explain:'بعد has نستخدم التصريف الثالث seen.'},{text:'They ___ never visited Japan.',options:['have','has','is'],answer:0,explain:'مع they نستخدم have.'}]),
    lesson('g-question-words','أدوات السؤال','ابدأ سؤالك بالكلمة التي تحدد المعلومة التي تبحث عنها.','إذا أردت معرفة المكان تسأل Where، وإذا أردت معرفة السبب تسأل Why. اختيار أداة السؤال يعتمد على نوع الإجابة التي تنتظرها.','Question word + auxiliary / be + subject + ...?',
      ['What للسؤال عن الشيء أو المعلومة.','Where للمكان، When للوقت، Why للسبب.','Who للشخص، وHow للطريقة أو الحال.','بعد أداة السؤال انتبه إلى ترتيب الفعل المساعد والفاعل.'],
      [{en:'Where do you live?',ar:'أين تسكن؟',focus:'Where'},{en:'When is your birthday?',ar:'متى عيد ميلادك؟',focus:'When'},{en:'Why are you late?',ar:'لماذا تأخرت؟',focus:'Why'}],
      {wrong:'Where you live?',right:'Where do you live?',why:'في هذا السؤال نحتاج do قبل الفاعل you.'},
      'فكّر في نوع الإجابة: مكان، شخص، وقت، سبب، شيء، أم طريقة؟',
      [{text:'___ is your name?',options:['What','Where','When'],answer:0,explain:'What للسؤال عن الاسم أو المعلومة.'},{text:'___ do you live?',options:['Who','Where','Why'],answer:1,explain:'Where للسؤال عن المكان.'},{text:'___ are you sad?',options:['When','How','Why'],answer:2,explain:'Why للسؤال عن السبب.'}]),
    lesson('g-articles','a / an / the','اختر أداة الاسم بحسب هل تتحدث عن شيء غير محدد أم شيء معروف، وانتبه إلى الصوت.','تقول a book عندما تذكر كتابًا غير محدد، ثم the book عندما يصبح معروفًا لك وللمستمع.','a + singular noun — an + vowel sound — the + specific noun',
      ['استخدم a قبل اسم مفرد معدود يبدأ بصوت ساكن.','استخدم an قبل اسم مفرد معدود يبدأ بصوت متحرك.','استخدم the عندما يكون الشيء محددًا أو معروفًا للطرفين.','الاختيار يعتمد على الصوت عند a وan، وليس على أول حرف فقط.'],
      [{en:'I saw a dog.',ar:'رأيت كلبًا (غير محدد).',focus:'a dog'},{en:'She ate an apple.',ar:'أكلت تفاحة.',focus:'an apple'},{en:'The sun is bright.',ar:'الشمس ساطعة.',focus:'The sun'}],
      {wrong:'an university',right:'a university',why:'كلمة university تبدأ بصوت /y/ الساكن، لذلك نستخدم a.'},
      'قل الكلمة بصوت مسموع: هل بدايتها صوت ساكن أم متحرك؟',
      [{text:'I ate ___ orange.',options:['a','an','the'],answer:1,explain:'orange تبدأ بصوت متحرك، لذلك نستخدم an.'},{text:'He has ___ new bag.',options:['a','an','are'],answer:0,explain:'bag اسم مفرد معدود يبدأ بصوت ساكن.'},{text:'___ moon goes around Earth.',options:['A','An','The'],answer:2,explain:'نتحدث عن القمر المعروف؛ لذلك نستخدم the.'}]),
    lesson('g-time-prepositions','حروف الجر للوقت: at / on / in','حدّد متى يحدث الشيء باستخدام at وon وin.','تخيل الوقت كدوائر: at لوقت دقيق، on ليوم أو تاريخ، in لفترة أوسع مثل شهر أو سنة.','at + clock time — on + day/date — in + month/year/period',
      ['استخدم at مع الساعة واللحظة المحددة: at 7:00.','استخدم on مع أيام الأسبوع والتواريخ: on Monday.','استخدم in مع الأشهر والسنوات والفصول والفترات: in July.','هناك تعبيرات خاصة تحفظ كما هي، مثل at night.'],
      [{en:'The class starts at 8:00.',ar:'يبدأ الدرس الساعة الثامنة.',focus:'at 8:00'},{en:'We meet on Friday.',ar:'نلتقي يوم الجمعة.',focus:'on Friday'},{en:'My birthday is in July.',ar:'عيد ميلادي في يوليو.',focus:'in July'}],
      {wrong:'at Monday',right:'on Monday',why:'نستخدم on مع أيام الأسبوع.'},
      'تذكّرها هكذا: AT نقطة، ON يوم، IN فترة.',
      [{text:'I wake up ___ six.',options:['at','on','in'],answer:0,explain:'الساعة وقت محدد؛ نستخدم at.'},{text:'The exam is ___ Sunday.',options:['in','on','at'],answer:1,explain:'نستخدم on مع أيام الأسبوع.'},{text:'School starts ___ September.',options:['at','in','on'],answer:1,explain:'نستخدم in مع الأشهر.'}]),
    lesson('g-countable-uncountable','الأسماء المعدودة وغير المعدودة','اعرف هل تستطيع عدّ الاسم بوحدات منفصلة، ثم اختر الكمية المناسبة.','تستطيع عدّ books واحدًا اثنين ثلاثة، لكن water لا نعدّه عادةً كقطع منفصلة. هذا الفرق يغيّر الكلمات التي نستخدمها مع الاسم.','many + countable plural — much + uncountable — a lot of + both',
      ['الاسم المعدود يمكن أن يأتي مفردًا أو جمعًا: book / books.','الاسم غير المعدود يأتي غالبًا بصيغة مفردة: water, rice, information.','استخدم many مع جمع المعدود وmuch مع غير المعدود.','استخدم a lot of مع النوعين في كثير من الجمل.'],
      [{en:'There are many books.',ar:'هناك كتب كثيرة.',focus:'many books'},{en:'We don’t have much water.',ar:'ليس لدينا ماء كثير.',focus:'much water'},{en:'She has a lot of friends.',ar:'لديها أصدقاء كثيرون.',focus:'a lot of'}],
      {wrong:'many water',right:'much water',why:'water غير معدود في هذا الاستخدام، لذلك نستخدم much.'},
      'بعض الأسماء غير المعدودة في الإنجليزية تختلف عن تصورنا بالعربية؛ تعلّمها ضمن عبارة.',
      [{text:'How ___ apples do you need?',options:['much','many','any'],answer:1,explain:'apples جمع معدود؛ نستخدم many.'},{text:'How ___ milk is there?',options:['many','few','much'],answer:2,explain:'milk غير معدود؛ نستخدم much.'},{text:'We have ___ of time.',options:['a lot','many','few'],answer:0,explain:'a lot of يمكن أن تأتي مع time.'}]),
    lesson('g-like-ing','like + ing أو like + to','عبّر عن الأشياء التي تحب فعلها باستخدام التركيب المناسب بعد like.','عندما تقول إنك تحب القراءة، فأنت تتحدث عن نشاط تستمتع به، وليس عن كتاب واحد فقط.','like + verb-ing — like + to + base verb',
      ['بعد like يمكنك استخدام فعل منتهٍ بـ ing.','يمكن أيضًا استخدام to ثم الفعل الأساسي.','كلا التركيبين صحيح في كثير من السياقات، وقد يختلف التركيز قليلًا.','لا تضع فعلًا عاريًا مباشرة بعد like في الجملة المعتادة.'],
      [{en:'I like playing football.',ar:'أحب لعب كرة القدم.',focus:'like playing'},{en:'She likes to read.',ar:'هي تحب القراءة.',focus:'likes to read'},{en:'We like watching films.',ar:'نحب مشاهدة الأفلام.',focus:'like watching'}],
      {wrong:'I like play football.',right:'I like playing football. / I like to play football.',why:'بعد like نستخدم غالبًا verb-ing أو to + الفعل الأساسي.'},
      'اختر صيغة واحدة صحيحة وثبّت عليها في الجملة.',
      [{text:'I enjoy ___ books.',options:['read','reading','reads'],answer:1,explain:'بعد enjoy نستخدم عادةً verb-ing.'},{text:'She likes ___ music.',options:['listening to','listen to','listens to'],answer:0,explain:'listening to هو تركيب ing الصحيح.'},{text:'They like ___ swim.',options:['to','swimming to','are'],answer:0,explain:'يمكن أن نقول like to swim.'}]),
    lesson('g-comparatives','المقارنة بين شيئين','قارن بين شخصين أو شيئين لتوضيح أن أحدهما أطول أو أسرع أو أكثر أهمية.','عندما تقارن بين هاتفين، لا تصف كل واحد فقط؛ بل تبيّن الفرق بينهما باستخدام صيغة المقارنة.','short adjective + -er + than — more + long adjective + than',
      ['مع كثير من الصفات القصيرة نضيف er: tall → taller.','مع كثير من الصفات الطويلة نستخدم more قبل الصفة.','استخدم than لربط طرفي المقارنة.','توجد صيغ غير منتظمة مثل good → better.'],
      [{en:'Ali is taller than Omar.',ar:'علي أطول من عمر.',focus:'taller than'},{en:'This book is more interesting than that one.',ar:'هذا الكتاب أكثر تشويقًا من ذاك.',focus:'more interesting'},{en:'Today is better than yesterday.',ar:'اليوم أفضل من أمس.',focus:'better than'}],
      {wrong:'more taller',right:'taller',why:'لا نستخدم more مع الصفة التي أخذت er في الصيغة نفسها.'},
      'اسأل: هل الصفة قصيرة غالبًا أم طويلة؟ ثم اختر er أو more.',
      [{text:'My brother is ___ than me. (tall)',options:['taller','more tall','tallest'],answer:0,explain:'نضيف er إلى الصفة القصيرة tall.'},{text:'This story is ___ interesting.',options:['most','more','mucher'],answer:1,explain:'نستخدم more مع الصفة الطويلة interesting.'},{text:'Good becomes ___ in the comparative.',options:['gooder','more good','better'],answer:2,explain:'better هي صيغة المقارنة غير المنتظمة من good.'}]),
    lesson('g-adverbs','الظروف: كيف يحدث الفعل؟','استخدم الظرف لتوضيح طريقة حدوث الفعل أو وقته أو مكانه.','هناك فرق بين أن تقول إن الشخص هادئ (صفة) وأنه يتحدث بهدوء (ظرف يصف طريقة الكلام).','verb + adverb — often adjective + -ly',
      ['الصفة تصف اسمًا: a quiet room.','الظرف يصف فعلًا غالبًا: speak quietly.','كثير من الظروف تتكون بإضافة ly: slow → slowly.','توجد استثناءات مهمة مثل fast وwell.'],
      [{en:'She speaks slowly.',ar:'هي تتحدث ببطء.',focus:'slowly'},{en:'He drives carefully.',ar:'هو يقود بحذر.',focus:'carefully'},{en:'The children run fast.',ar:'الأطفال يركضون بسرعة.',focus:'fast'}],
      {wrong:'She speaks slow.',right:'She speaks slowly.',why:'نحتاج إلى ظرف يوضح كيف تتحدث، لا صفة تصف اسمًا.'},
      'لا تضف ly آليًا لكل كلمة؛ بعض الظروف مثل fast لا تتغير.',
      [{text:'He runs ___. (quick)',options:['quick','quickly','quicker'],answer:1,explain:'quickly ظرف يصف طريقة الجري.'},{text:'She sings ___. (beautiful)',options:['beautifully','beautiful','beautify'],answer:0,explain:'نحوّل beautiful إلى beautifully.'},{text:'The car moves ___.',options:['fast','fastly','fasterly'],answer:0,explain:'fast ظرف صحيح ولا نضيف إليه ly.'}]),
    lesson('g-negatives-do-does','النفي باستخدام don’t وdoesn’t','حوّل الجملة المثبتة إلى نفي في المضارع البسيط.','إذا كنت لا تلعب كرة القدم، تستطيع قول I don’t play football. الأداة do أو does تساعدك على بناء النفي.','I / you / we / they + don’t + base verb — he / she / it + doesn’t + base verb',
      ['استخدم don’t مع I وyou وwe وthey.','استخدم doesn’t مع he وshe وit والاسم المفرد.','بعد don’t وdoesn’t استخدم الفعل الأساسي دون s.','ضع not في الصيغة الكاملة: do not أو does not.'],
      [{en:'I don’t drink coffee.',ar:'أنا لا أشرب القهوة.',focus:'don’t drink'},{en:'She doesn’t play tennis.',ar:'هي لا تلعب التنس.',focus:'doesn’t play'},{en:'They don’t live here.',ar:'هم لا يسكنون هنا.',focus:'don’t live'}],
      {wrong:'He doesn’t plays.',right:'He doesn’t play.',why:'doesn’t تحمل علامة المفرد؛ لذلك لا نضيف s إلى الفعل بعدها.'},
      'إذا كتبت doesn’t، احذف s من الفعل الذي بعدها.',
      [{text:'He ___ like tea.',options:['don’t','doesn’t','isn’t'],answer:1,explain:'مع he نستخدم doesn’t.'},{text:'We ___ watch TV every night.',options:['doesn’t','aren’t','don’t'],answer:2,explain:'مع we نستخدم don’t.'},{text:'She doesn’t ___ early.',options:['wakes','wake','waking'],answer:1,explain:'بعد doesn’t نستخدم الفعل الأساسي wake.'}]),
    lesson('g-present-simple-questions','أسئلة المضارع البسيط','كوّن سؤالًا عن العادات والحقائق باستخدام Do أو Does.','تريد أن تسأل صديقك: هل تحب الإنجليزية؟ ابدأ بـ Do ثم you ثم الفعل الأساسي.','Do / Does + subject + base verb + ...?',
      ['ابدأ بـ Do مع I وyou وwe وthey.','ابدأ بـ Does مع he وshe وit.','ضع الفاعل بعد Do أو Does.','استخدم الفعل الأساسي دون s بعد Does.'],
      [{en:'Do you speak English?',ar:'هل تتحدث الإنجليزية؟',focus:'Do you speak'},{en:'Does she study every day?',ar:'هل تدرس كل يوم؟',focus:'Does she study'},{en:'Where do they live?',ar:'أين يسكنون؟',focus:'do they live'}],
      {wrong:'Does she likes music?',right:'Does she like music?',why:'بعد Does يعود الفعل إلى صورته الأساسية.'},
      'في السؤال، Does تحمل علامة he/she/it؛ لا تكررها على الفعل.',
      [{text:'___ you play football?',options:['Do','Does','Are'],answer:0,explain:'مع you نستخدم Do.'},{text:'___ he work here?',options:['Do','Does','Is'],answer:1,explain:'مع he نستخدم Does.'},{text:'Does your sister ___ English?',options:['speaks','speaking','speak'],answer:2,explain:'بعد Does يأتي الفعل الأساسي speak.'}]),
    lesson('g-there-is-are','there is / there are','أخبر الآخرين أن شيئًا أو أشخاصًا موجودون في مكان ما.','تصف غرفتك: يوجد كرسي، وهناك كتابان على الطاولة. هذه الجمل تبدأ غالبًا بـ There is أو There are.','There is + singular — There are + plural',
      ['استخدم There is مع اسم مفرد أو غير معدود.','استخدم There are مع اسم جمع.','للنفي أضف not بعد is أو are.','للسؤال ابدأ بـ Is there أو Are there.'],
      [{en:'There is a book on the desk.',ar:'يوجد كتاب على المكتب.',focus:'There is'},{en:'There are two windows.',ar:'توجد نافذتان.',focus:'There are'},{en:'Is there a park near here?',ar:'هل توجد حديقة بالقرب من هنا؟',focus:'Is there'}],
      {wrong:'There is two students.',right:'There are two students.',why:'two students جمع؛ لذلك نستخدم are.'},
      'انظر إلى الاسم الذي يأتي بعد there: مفرد أم جمع؟',
      [{text:'There ___ a cat in the room.',options:['are','is','am'],answer:1,explain:'a cat مفرد؛ نستخدم is.'},{text:'There ___ three chairs.',options:['is','are','be'],answer:1,explain:'three chairs جمع؛ نستخدم are.'},{text:'___ there any milk?',options:['Are','Is','Do'],answer:1,explain:'milk غير معدود؛ نستخدم Is there.'}]),
    lesson('g-have-has','have / has','تحدث عن الملكية أو الأشياء التي يمتلكها شخص.','تقول: لدي كتاب، ولدى أختي هاتف جديد. اختيار have أو has يتغير بحسب الفاعل.','I / you / we / they + have — he / she / it + has',
      ['استخدم have مع I وyou وwe وthey.','استخدم has مع he وshe وit والاسم المفرد.','في النفي والسؤال بالمضارع البسيط نستخدم do/does مع have.','لا تقل does she has؛ بل does she have.'],
      [{en:'I have a new book.',ar:'لدي كتاب جديد.',focus:'have'},{en:'She has a small dog.',ar:'لديها كلب صغير.',focus:'has'},{en:'Do they have a car?',ar:'هل لديهم سيارة؟',focus:'Do ... have'}],
      {wrong:'Does he has a pen?',right:'Does he have a pen?',why:'بعد Does نستخدم have بصيغته الأساسية.'},
      'في الجملة المثبتة: he has. أما بعد does فقل have.',
      [{text:'They ___ two brothers.',options:['has','have','having'],answer:1,explain:'مع they نستخدم have.'},{text:'My mother ___ a car.',options:['have','has','having'],answer:1,explain:'my mother مفرد؛ نستخدم has.'},{text:'Does she ___ a phone?',options:['has','have','having'],answer:1,explain:'بعد Does نستخدم have.'}]),
    lesson('g-possessive-adjectives','صفات الملكية','بيّن لمن ينتمي الشيء باستخدام my وyour وhis وغيرها.','عندما تقول كتابي، فأنت لا تحتاج إلى تكرار عبارة الكتاب الذي أملكه؛ صفة الملكية تختصر المعنى وتأتي قبل الاسم.','possessive adjective + noun',
      ['my للمتكلم المفرد، your للمخاطب.','his للمذكر، her للمؤنث، its لغير العاقل.','our لنا، their لهم.','صفة الملكية تأتي قبل الاسم الذي تملكه.'],
      [{en:'This is my book.',ar:'هذا كتابي.',focus:'my'},{en:'Her bag is blue.',ar:'حقيبتها زرقاء.',focus:'Her'},{en:'Their teacher is kind.',ar:'معلمهم لطيف.',focus:'Their'}],
      {wrong:'This is me book.',right:'This is my book.',why:'نحتاج صفة الملكية my قبل الاسم، لا ضمير المفعول me.'},
      'لا تخلط بين his وher: اخترها بحسب صاحب الشيء، لا بحسب الشيء نفسه.',
      [{text:'I have a sister. ___ name is Sara.',options:['Her','His','Our'],answer:0,explain:'صاحبة الاسم sister؛ نستخدم Her.'},{text:'We love ___ school.',options:['their','our','his'],answer:1,explain:'We تعني نحن؛ صفة الملكية هي our.'},{text:'The dog is eating ___ food.',options:['their','his','its'],answer:2,explain:'مع الحيوان غير المحدد نستخدم its.'}]),
    lesson('g-object-pronouns','ضمائر المفعول','استخدم me وhim وher وغيرها عندما يقع الفعل على شخص أو شيء.','في جملة I help him، كلمة I هي من يقوم بالفعل، وhim هو الشخص الذي يتلقى المساعدة.','verb / preposition + object pronoun',
      ['ضمائر الفاعل: I, he, she, we, they.','ضمائر المفعول المقابلة: me, him, her, us, them.','تأتي ضمائر المفعول بعد الفعل أو حرف الجر غالبًا.','you وit لهما الشكل نفسه في الفاعل والمفعول.'],
      [{en:'Please help me.',ar:'من فضلك ساعدني.',focus:'me'},{en:'I called him yesterday.',ar:'اتصلت به أمس.',focus:'him'},{en:'This gift is for them.',ar:'هذه الهدية لهم.',focus:'them'}],
      {wrong:'She helps I.',right:'She helps me.',why:'بعد الفعل help نستخدم ضمير المفعول me.'},
      'اسأل: من يفعل؟ فاعل. من يقع عليه الفعل؟ مفعول.',
      [{text:'My friend called ___.',options:['I','me','my'],answer:1,explain:'بعد called نستخدم ضمير المفعول me.'},{text:'I saw Sara. I saw ___.',options:['she','her','hers'],answer:1,explain:'Sara مؤنث؛ ضمير المفعول هو her.'},{text:'Please listen to ___.',options:['we','our','us'],answer:2,explain:'بعد to نستخدم ضمير المفعول us.'}]),
    lesson('g-some-any','some و any','تحدث عن كمية غير محددة دون ذكر رقم دقيق.','تسأل صديقك إذا كان لديه أي أسئلة، أو تعرض عليه بعض الماء. هنا تظهر some وany.','some: often in affirmative / offers — any: often in negatives and questions',
      ['استخدم some غالبًا في الجمل المثبتة.','استخدم any غالبًا في النفي والأسئلة.','تُستخدم some في العروض والطلبات عندما تتوقع القبول.','اختر الاسم المعدود الجمع أو غير المعدود بعدهما بحسب المعنى.'],
      [{en:'I have some friends.',ar:'لدي بعض الأصدقاء.',focus:'some'},{en:'Do you have any questions?',ar:'هل لديك أي أسئلة؟',focus:'any'},{en:'Would you like some water?',ar:'هل ترغب في بعض الماء؟',focus:'some'}],
      {wrong:'I don’t have some money.',right:'I don’t have any money.',why:'في النفي نستخدم any غالبًا.'},
      'هذه قاعدة شائعة وليست آلية مطلقة؛ some قد تظهر في السؤال عند العرض أو الطلب.',
      [{text:'I bought ___ apples.',options:['some','any','much'],answer:0,explain:'جملة مثبتة؛ some مناسبة.'},{text:'I don’t have ___ time.',options:['some','any','many'],answer:1,explain:'في النفي نستخدم any غالبًا.'},{text:'Would you like ___ tea?',options:['any','some','many'],answer:1,explain:'في العرض المهذب نستخدم some غالبًا.'}]),
    lesson('g-much-many-lot-of','much / many / a lot of','اختر أداة الكمية المناسبة بحسب نوع الاسم.','إذا كنت تعدّ الكتب فقل many books، وإذا كنت تتحدث عن الماء فقل much water. ويمكنك استخدام a lot of مع الاثنين.','many + countable plural — much + uncountable — a lot of + both',
      ['many مع الأسماء المعدودة الجمع.','much مع الأسماء غير المعدودة.','a lot of يمكن أن تأتي مع المعدود وغير المعدود.','في الإثبات اليومي، a lot of شائعة جدًا، بينما much أكثر شيوعًا في النفي والسؤال.'],
      [{en:'I have many books.',ar:'لدي كتب كثيرة.',focus:'many books'},{en:'We don’t have much time.',ar:'ليس لدينا وقت كثير.',focus:'much time'},{en:'She drinks a lot of water.',ar:'تشرب الكثير من الماء.',focus:'a lot of water'}],
      {wrong:'much friends',right:'many friends',why:'friends أسماء معدودة بصيغة الجمع؛ نستخدم many.'},
      'حدد أولًا: هل تستطيع عدّ الاسم كأشياء منفصلة؟',
      [{text:'How ___ students are there?',options:['much','many','a little'],answer:1,explain:'students جمع معدود؛ نستخدم many.'},{text:'How ___ sugar do you need?',options:['many','much','few'],answer:1,explain:'sugar غير معدود؛ نستخدم much.'},{text:'There is ___ of food.',options:['a lot','many','few'],answer:0,explain:'a lot of يناسب food غير المعدود.'}]),
    lesson('g-place-prepositions','حروف الجر للمكان','صف موقع الأشياء باستخدام in وon وunder وbetween وغيرها.','تشرح لصديقك أين وضعت حقيبتك: داخل الخزانة، على الطاولة، أو تحت الكرسي. حروف الجر تجعل المكان واضحًا.','preposition of place + noun',
      ['in تعني داخل شيء أو مكان.','on تعني على سطح شيء.','under تعني أسفل شيء.','between تعني بين شيئين، وnext to تعني بجانب.'],
      [{en:'The keys are in my bag.',ar:'المفاتيح داخل حقيبتي.',focus:'in'},{en:'The book is on the table.',ar:'الكتاب على الطاولة.',focus:'on'},{en:'The cat is under the chair.',ar:'القطة تحت الكرسي.',focus:'under'}],
      {wrong:'The book is in the table.',right:'The book is on the table.',why:'إذا كان الكتاب فوق سطح الطاولة نستخدم on، لا in.'},
      'ارسم المكان في ذهنك: داخل، فوق سطح، أسفل، أم بجانب؟',
      [{text:'The milk is ___ the fridge.',options:['in','on','under'],answer:0,explain:'الحليب داخل الثلاجة؛ نستخدم in.'},{text:'The picture is ___ the wall.',options:['under','on','between'],answer:1,explain:'الصورة على سطح الجدار؛ التعبير المعتاد on the wall.'},{text:'The shoes are ___ the bed.',options:['under','in','on'],answer:0,explain:'أسفل السرير تعني under the bed.'}]),
    lesson('g-can-cant','can وcan’t','عبّر عن القدرة أو عدم القدرة أو الإمكانية.','تستطيع السباحة؟ قل I can swim. لا تستطيع القيادة؟ قل I can’t drive. الكلمة لا تتغير بحسب الفاعل.','subject + can / can’t + base verb',
      ['استخدم can للقدرة أو الإمكانية.','استخدم cannot أو can’t لعدم القدرة.','بعد can يأتي الفعل الأساسي دون to.','في السؤال قدّم can إلى بداية الجملة.'],
      [{en:'I can swim.',ar:'أستطيع السباحة.',focus:'can swim'},{en:'She can speak English.',ar:'هي تستطيع التحدث بالإنجليزية.',focus:'can speak'},{en:'Can you help me?',ar:'هل تستطيع مساعدتي؟',focus:'Can you'}],
      {wrong:'He can swims.',right:'He can swim.',why:'بعد can نستخدم الفعل الأساسي حتى مع he أو she.'},
      'can واحدة مع جميع الضمائر؛ لا تضف s ولا to بعدها.',
      [{text:'I can ___ English.',options:['speaks','speak','speaking'],answer:1,explain:'بعد can نستخدم الفعل الأساسي speak.'},{text:'She ___ drive. (not able)',options:['can’t','doesn’t can','cans not'],answer:0,explain:'النفي يكون can’t أو cannot.'},{text:'___ you swim?',options:['Do','Are','Can'],answer:2,explain:'للسؤال عن القدرة نبدأ بـ Can.'}]),
    lesson('g-must-should','must وshould','فرّق بين الضرورة القوية والنصيحة.','عندما تكون قاعدة السلامة إلزامية تستخدم must. وعندما تنصح صديقك بالنوم مبكرًا تستخدم should.','must / should + base verb',
      ['must للتعبير عن ضرورة أو إلزام قوي.','should لتقديم نصيحة أو اقتراح.','بعد الكلمتين يأتي الفعل الأساسي مباشرة.','النفي يختلف في المعنى: mustn’t تعني ممنوع، وshouldn’t تعني لا يُنصح.'],
      [{en:'You must wear a seat belt.',ar:'يجب أن ترتدي حزام الأمان.',focus:'must wear'},{en:'You should drink enough water.',ar:'ينبغي أن تشرب ماءً كافيًا.',focus:'should drink'},{en:'You shouldn’t stay up too late.',ar:'لا ينبغي أن تسهر كثيرًا.',focus:'shouldn’t'}],
      {wrong:'You should to study.',right:'You should study.',why:'لا نضع to بعد should أو must.'},
      'احفظ الفرق: must إلزام، should نصيحة.',
      [{text:'You ___ stop at a red light.',options:['must','should to','musts'],answer:0,explain:'هذه قاعدة إلزامية؛ must مناسبة.'},{text:'You ___ rest if you are tired.',options:['must to','should','shoulds'],answer:1,explain:'هذه نصيحة؛ should مناسبة.'},{text:'After must, use ___.',options:['to + verb','verb-ing','base verb'],answer:2,explain:'بعد must نستخدم الفعل الأساسي.'}]),
    lesson('g-imperatives','صيغة الأمر والطلب','أعطِ تعليمات أو طلبات مباشرة بصيغة الفعل الأساسي.','في الصف قد يقول المعلم: Open your book. هذه تعليمة تبدأ بالفعل مباشرة.','base verb + ... — negative: Don’t + base verb',
      ['ابدأ بالفعل الأساسي دون فاعل ظاهر غالبًا.','يمكن إضافة please لجعل الطلب ألطف.','للنهي ابدأ بـ Don’t ثم الفعل الأساسي.','يمكن أن تضيف مفعولًا أو مكانًا أو وقتًا بعد الفعل.'],
      [{en:'Open your book, please.',ar:'افتح كتابك من فضلك.',focus:'Open'},{en:'Listen carefully.',ar:'استمع جيدًا.',focus:'Listen'},{en:'Don’t run in the hallway.',ar:'لا تركض في الممر.',focus:'Don’t run'}],
      {wrong:'To open your book.',right:'Open your book.',why:'صيغة الأمر تبدأ بالفعل الأساسي، ولا نضع to في بدايتها.'},
      'الأمر لا يعني دائمًا الصراخ؛ أضف please ليصبح طلبًا مهذبًا.',
      [{text:'___ the door, please.',options:['Open','Opens','Opening'],answer:0,explain:'نستخدم الفعل الأساسي في بداية الأمر.'},{text:'___ touch the screen.',options:['Not','Don’t','Doesn’t'],answer:1,explain:'للنهي نستخدم Don’t + الفعل الأساسي.'},{text:'Choose a polite request.',options:['Give me it!','Please sit down.','You sits.'],answer:1,explain:'إضافة please تجعل الطلب مهذبًا.'}]),
    lesson('g-because-so','because وso','اربط السبب بالنتيجة دون الخلط بينهما.','فاتك الحافلة لأنك استيقظت متأخرًا. يمكنك ذكر السبب باستخدام because، أو ذكر النتيجة باستخدام so.','result + because + reason — reason + so + result',
      ['because تقدم السبب: لماذا حدث الشيء؟','so تقدم النتيجة: ماذا حدث بسبب ذلك؟','لا تضع because وso معًا بالطريقة نفسها في جملة واحدة بسيطة.','اقرأ الجملة وتأكد أن ترتيب السبب والنتيجة منطقي.'],
      [{en:'I stayed home because I was sick.',ar:'بقيت في المنزل لأنني كنت مريضًا.',focus:'because'},{en:'I was tired, so I went to bed.',ar:'كنت متعبًا، لذلك ذهبت إلى النوم.',focus:'so'},{en:'She studied hard, so she passed.',ar:'درست بجد، لذلك نجحت.',focus:'so'}],
      {wrong:'Because I was tired, so I slept.',right:'Because I was tired, I slept. / I was tired, so I slept.',why:'اختر أداة واحدة بحسب تركيب الجملة؛ لا تجمعهما بهذه الصورة.'},
      'اسأل: هل أشرح السبب؟ because. هل أذكر النتيجة؟ so.',
      [{text:'I was hungry, ___ I made a sandwich.',options:['because','so','but'],answer:1,explain:'صنع الشطيرة نتيجة الجوع؛ نستخدم so.'},{text:'I stayed inside ___ it was raining.',options:['because','so','and'],answer:0,explain:'المطر هو السبب؛ نستخدم because.'},{text:'Which one introduces a reason?',options:['so','because','therefore'],answer:1,explain:'because تقدم السبب.'}]),
    lesson('g-one-ones','one وones لتجنب التكرار','استبدل اسمًا معروفًا حتى لا تكرره في الجملة.','إذا سألك صديقك: أي حقيبة تريد؟ تستطيع أن تقول the blue one بدل تكرار كلمة bag.','one = singular noun replacement — ones = plural noun replacement',
      ['استخدم one بدل اسم مفرد معروف من السياق.','استخدم ones بدل اسم جمع معروف.','يمكن وضع صفة قبل one أو ones: the red one.','تأكد أن العدد مفرد أو جمع.'],
      [{en:'I like the blue one.',ar:'أحب الأزرق (أي الشيء الأزرق).',focus:'one'},{en:'These shoes are nice. I want the black ones.',ar:'هذه الأحذية جميلة. أريد السوداء.',focus:'ones'},{en:'Which pencil? The short one.',ar:'أي قلم؟ القصير.',focus:'one'}],
      {wrong:'I like the blue ones. (when choosing one bag)',right:'I like the blue one.',why:'عندما تختار حقيبة واحدة تستخدم one.'},
      'انظر إلى الاسم الذي حُذف: مفرد أم جمع؟',
      [{text:'I want the green ___. (one shirt)',options:['one','ones','them'],answer:0,explain:'shirt مفرد؛ نستخدم one.'},{text:'These are the shoes I like: the white ___.',options:['one','ones','it'],answer:1,explain:'shoes جمع؛ نستخدم ones.'},{text:'Which phone? The new ___.',options:['ones','one','they'],answer:1,explain:'phone مفرد؛ نستخدم one.'}]),
    lesson('g-too-enough','too وenough','عبّر عن أن الشيء أكثر من اللازم أو أنه بالمقدار الكافي.','الحقيبة ثقيلة جدًا؟ too heavy. هل أنت قوي بما يكفي لحملها؟ strong enough. ترتيب الكلمة يوضح المعنى.','too + adjective — adjective + enough — enough + noun',
      ['too تأتي قبل الصفة: too expensive.','enough تأتي بعد الصفة: tall enough.','enough تأتي قبل الاسم: enough time.','too غالبًا تعني أن الدرجة زائدة وغير مناسبة، أما enough فتعني الكفاية.'],
      [{en:'This bag is too heavy.',ar:'هذه الحقيبة ثقيلة أكثر من اللازم.',focus:'too heavy'},{en:'He is old enough to drive.',ar:'عمره مناسب بما يكفي للقيادة.',focus:'old enough'},{en:'We have enough time.',ar:'لدينا وقت كافٍ.',focus:'enough time'}],
      {wrong:'She is enough tall.',right:'She is tall enough.',why:'enough تأتي بعد الصفة، لكنها تأتي قبل الاسم.'},
      'تذكّر مكان enough: بعد الصفة، وقبل الاسم.',
      [{text:'The coffee is ___ hot to drink.',options:['enough','too','many'],answer:1,explain:'too تأتي قبل الصفة hot.'},{text:'He is strong ___ to lift it.',options:['too','enough','much'],answer:1,explain:'enough تأتي بعد الصفة strong.'},{text:'We have ___ food for everyone.',options:['enough','too','many'],answer:0,explain:'enough تأتي قبل الاسم food.'}]),
    lesson('g-enjoy-ing','الأفعال التي يأتي بعدها ing: enjoy','تعلّم الأفعال التي تتبعها صيغة ing حتى تبني الجملة بصورة طبيعية.','بعض الأفعال مثل enjoy تتبعها صيغة ing عادةً. لذلك نقول I enjoy reading وليس I enjoy to read.','enjoy + verb-ing',
      ['بعد enjoy نستخدم الفعل المنتهي بـ ing.','أضف ing مع الانتباه لتغيير الإملاء عند الحاجة: make → making.','يمكن أن يأتي بعده اسم بدل الفعل: enjoy music.','لا تخلط بين enjoy وlike؛ فـ like تقبل ing أو to + verb غالبًا.'],
      [{en:'I enjoy reading.',ar:'أستمتع بالقراءة.',focus:'enjoy reading'},{en:'They enjoy playing games.',ar:'يستمتعون بلعب الألعاب.',focus:'enjoy playing'},{en:'She enjoys cooking.',ar:'تستمتع بالطبخ.',focus:'enjoys cooking'}],
      {wrong:'I enjoy to swim.',right:'I enjoy swimming.',why:'بعد enjoy نستخدم verb-ing.'},
      'احفظ enjoy مع ing كأنهما كلمة واحدة.',
      [{text:'We enjoy ___ together.',options:['study','studying','to studying'],answer:1,explain:'بعد enjoy نستخدم studying.'},{text:'He enjoys ___.',options:['cook','cooking','to cook'],answer:1,explain:'enjoys يتبعها cooking.'},{text:'Which sentence is correct?',options:['I enjoy to read.','I enjoy reading.','I enjoying read.'],answer:1,explain:'التركيب الصحيح هو enjoy + verb-ing.'}]),
    lesson('g-first-conditional','الشرط الأول','تحدث عن نتيجة مستقبلية محتملة إذا تحقق شرط معين.','إذا هطل المطر، سنبقى في المنزل. المطر احتمال حقيقي في المستقبل، والنتيجة تعتمد عليه.','If + present simple, will + base verb',
      ['ابدأ بجملة الشرط باستخدام If.','استخدم المضارع البسيط في جملة الشرط.','استخدم will مع الفعل الأساسي في جملة النتيجة.','يمكن تبديل ترتيب الجزأين دون تغيير المعنى الأساسي.'],
      [{en:'If it rains, we will stay home.',ar:'إذا أمطرت، فسنبقى في المنزل.',focus:'If it rains'},{en:'If you study, you will improve.',ar:'إذا درست، فسوف تتحسن.',focus:'you will improve'},{en:'I will call you if I arrive early.',ar:'سأتصل بك إذا وصلت مبكرًا.',focus:'if I arrive'}],
      {wrong:'If it will rain, we will stay home.',right:'If it rains, we will stay home.',why:'في الشرط الأول نستخدم المضارع البسيط بعد If، لا will عادةً.'},
      'بعد If استخدم المضارع البسيط، حتى لو كان المعنى متعلقًا بالمستقبل.',
      [{text:'If she ___ hard, she will pass.',options:['studies','will study','study'],answer:0,explain:'بعد If نستخدم المضارع البسيط.'},{text:'If it rains, we ___ inside.',options:['stayed','will stay','stay yesterday'],answer:1,explain:'النتيجة المستقبلية تستخدم will + base verb.'},{text:'Choose the correct sentence.',options:['If I will see him, I will tell him.','If I see him, I will tell him.','If I saw him, I tell him.'],answer:1,explain:'المضارع البسيط بعد If وwill في النتيجة.'}],'متوسط'),
    lesson('g-passive-voice','المبني للمجهول','ركّز على الفعل أو الشيء الذي وقع عليه الفعل بدل التركيز على من قام به.','إذا كان المهم أن اللغة الإنجليزية تُستخدم في دول كثيرة، قد تقول English is spoken in many countries دون ذكر المتحدثين.','subject + be (correct tense) + past participle',
      ['اجعل الشيء الذي وقع عليه الفعل في بداية الجملة.','اختر فعل be بالزمن المناسب: is أو was أو will be.','أضف التصريف الثالث للفعل.','يمكن ذكر الفاعل باستخدام by إذا كان مهمًا.'],
      [{en:'English is spoken here.',ar:'تُتحدث الإنجليزية هنا.',focus:'is spoken'},{en:'The window was broken.',ar:'كُسرت النافذة.',focus:'was broken'},{en:'The work will be finished tomorrow.',ar:'سيتم إنهاء العمل غدًا.',focus:'will be finished'}],
      {wrong:'The book is write by Ali.',right:'The book is written by Ali.',why:'المبني للمجهول يحتاج التصريف الثالث written.'},
      'تأكد من شيئين: فعل be في الزمن الصحيح، والتصريف الثالث بعده.',
      [{text:'The room ___ cleaned every day.',options:['is','are','does'],answer:0,explain:'room مفرد؛ المبني للمجهول في المضارع هو is cleaned.'},{text:'The cake was ___.',options:['make','made','making'],answer:1,explain:'بعد was نستخدم التصريف الثالث made.'},{text:'The letters will ___ sent tomorrow.',options:['be','is','are'],answer:0,explain:'المستقبل في المبني للمجهول: will be + التصريف الثالث.'}],'متوسط'),
    lesson('g-relative-clauses','جمل الوصل: who / which / that','أضف معلومات عن شخص أو شيء دون بدء جملة جديدة.','بدل أن تقول لدي صديق. هذا الصديق يحب القراءة. تستطيع دمج المعلومتين: لدي صديق يحب القراءة.','person + who / thing + which — that can refer to people or things',
      ['who تستخدم غالبًا للإشارة إلى الأشخاص.','which تستخدم غالبًا للأشياء والحيوانات.','that يمكن أن تستخدم للأشخاص أو الأشياء في جمل الوصل المحددة.','ضع جملة الوصل بعد الاسم الذي تشرح عنه.'],
      [{en:'The boy who won is my friend.',ar:'الولد الذي فاز هو صديقي.',focus:'who won'},{en:'This is the book that I bought.',ar:'هذا هو الكتاب الذي اشتريته.',focus:'that I bought'},{en:'I like films which teach me something.',ar:'أحب الأفلام التي تعلمني شيئًا.',focus:'which teach'}],
      {wrong:'The girl which helped me...',right:'The girl who helped me...',why:'who هي الاختيار المعتاد عند الحديث عن الأشخاص.'},
      'حدد الاسم أولًا: شخص أم شيء؟ ثم اختر أداة الوصل المناسبة.',
      [{text:'The teacher ___ helped us is kind.',options:['which','who','where'],answer:1,explain:'teacher شخص؛ نستخدم who.'},{text:'This is the phone ___ I bought.',options:['who','when','which'],answer:2,explain:'phone شيء؛ نستخدم which.'},{text:'The book ___ I read was useful.',options:['that','who','where'],answer:0,explain:'that مناسبة للأشياء في هذه الجملة.'}],'متوسط'),
    lesson('g-reported-speech','الكلام المنقول','انقل كلام شخص آخر دون تكرار كلماته حرفيًا.','قال صديقك: I am tired. عندما تخبر شخصًا آخر بما قاله، قد تقول: He said that he was tired.','said (that) + reported clause',
      ['ابدأ غالبًا بـ said أو told بحسب وجود الشخص الذي وُجه إليه الكلام.','قد يتغير الضمير ليتناسب مع المتحدث.','قد يرجع الزمن خطوة إلى الماضي عندما يكون فعل النقل في الماضي.','التغييرات ليست آلية دائمًا؛ تعتمد على الزمن والسياق وما زال صحيحًا.'],
      [{en:'“I am tired.” → He said that he was tired.',ar:'أنا متعب ← قال إنه كان متعبًا.',focus:'was tired'},{en:'“I like English.” → She said that she liked English.',ar:'أحب الإنجليزية ← قالت إنها تحب الإنجليزية.',focus:'liked'},{en:'“We are ready.” → They said that they were ready.',ar:'نحن مستعدون ← قالوا إنهم مستعدون.',focus:'were ready'}],
      {wrong:'She said me that she was happy.',right:'She told me that she was happy. / She said that she was happy.',why:'نستخدم told مع الشخص المتلقي، أو said دون مفعول مباشر بهذه الصورة.'},
      'ابدأ بتغيير الضمير، ثم افحص الزمن، ولا تغيّر كل شيء دون فهم السياق.',
      [{text:'“I am happy.” → He said he ___ happy.',options:['is','was','be'],answer:1,explain:'قد يرجع am إلى was عند النقل في الماضي.'},{text:'“We are ready.” → They said they ___ ready.',options:['were','was','are be'],answer:0,explain:'we are تصبح they were في المثال المنقول.'},{text:'Choose the correct form.',options:['She told me she was tired.','She said me she tired.','She told that tired.'],answer:0,explain:'told me تركيب صحيح مع الشخص المتلقي.'}],'متوسط'),
    lesson('g-phrasal-verbs','الأفعال المركبة','افهم كيف يتغير معنى الفعل عندما يأتي معه حرف جر أو ظرف.','الفعل look وحده له معنى، لكن look for تعني يبحث عن. لذلك تعلّم العبارة كاملة بدل ترجمة كل كلمة وحدها.','verb + particle (adverb / preposition) = a new meaning',
      ['تعلّم الفعل مع الكلمة التي تأتي بعده كوحدة واحدة.','لاحظ أن المعنى قد يختلف عن معنى الفعل منفردًا.','بعض الأفعال المركبة تقبل فصل المفعول، وبعضها لا؛ تعلّم نمط كل فعل.','استخدم مثالًا قصيرًا من الحياة اليومية لتثبيت المعنى.'],
      [{en:'Please turn off the light.',ar:'من فضلك أطفئ الضوء.',focus:'turn off'},{en:'I am looking for my keys.',ar:'أبحث عن مفاتيحي.',focus:'looking for'},{en:'Wake up early.',ar:'استيقظ مبكرًا.',focus:'wake up'}],
      {wrong:'I look my keys for.',right:'I look for my keys.',why:'look for عبارة مركبة يأتي مفعولها بعد for.'},
      'لا تحفظ look أو turn فقط؛ احفظ look for وturn off مع جملة.',
      [{text:'Please ___ the TV. (stop its power)',options:['turn off','look for','wake up'],answer:0,explain:'turn off تعني أطفئ.'},{text:'I can’t find my bag. I will ___ it.',options:['turn off','look for','get up'],answer:1,explain:'look for تعني أبحث عن.'},{text:'I ___ at 6 a.m. every day.',options:['wake up','turn on','look after'],answer:0,explain:'wake up تعني أستيقظ.'}])
  ];

  const tenses = [
    lesson('t-past-perfect','Past Perfect — الماضي التام','وضّح أن حدثًا وقع قبل حدث آخر في الماضي.','وصلت إلى المحطة، لكن القطار كان قد غادر قبل وصولك. نحتاج زمنًا يوضح أن المغادرة حدثت أولًا.','had + past participle',
      ['استخدم had مع جميع الضمائر.','ضع التصريف الثالث للفعل بعد had.','استخدمه لحدث اكتمل قبل نقطة أو حدث آخر في الماضي.','قد تظهر معه before وafter وby the time.'],
      [{en:'The train had left before I arrived.',ar:'كان القطار قد غادر قبل أن أصل.',focus:'had left'},{en:'She had finished dinner when I called.',ar:'كانت قد أنهت العشاء عندما اتصلت.',focus:'had finished'},{en:'By the time we came, they had gone.',ar:'بحلول وصولنا، كانوا قد ذهبوا.',focus:'had gone'}],
      {wrong:'They had went home.',right:'They had gone home.',why:'بعد had نستخدم التصريف الثالث gone.'},
      'في القصة الماضية، حدّد الحدث الأقدم؛ غالبًا هو الذي يأخذ had + التصريف الثالث.',
      [{text:'The bus had ___ before we arrived.',options:['leave','left','leaving'],answer:1,explain:'left هو التصريف الثالث من leave.'},{text:'She ___ finished before noon.',options:['had','has','have'],answer:0,explain:'الماضي التام يستخدم had.'},{text:'Choose the earlier action.',options:['I arrived.','The train had left.','I am arriving.'],answer:1,explain:'had left يوضح أن المغادرة سبقت الوصول.'}],'متوسط'),
    lesson('t-future-continuous','Future Continuous — المستقبل المستمر','لحدث سيكون جاريًا في وقت محدد في المستقبل.','تخيل أن أحدهم يتصل بك غدًا الساعة الثامنة؛ يمكنك أن تقول إنك ستكون تدرس في ذلك الوقت.','will be + verb-ing',
      ['استخدم will be بعد الفاعل.','أضف ing إلى الفعل.','استخدمه للتركيز على أن الفعل سيكون مستمرًا في وقت مستقبلي محدد.','قد تظهر معه at this time tomorrow أو at 8 tomorrow.'],
      [{en:'At 8, I will be studying.',ar:'سأكون أدرس الساعة الثامنة.',focus:'will be studying'},{en:'This time tomorrow, we will be flying.',ar:'في مثل هذا الوقت غدًا سنكون على متن الطائرة.',focus:'will be flying'},{en:'She will be working tonight.',ar:'ستكون تعمل الليلة.',focus:'will be working'}],
      {wrong:'I will studying at eight.',right:'I will be studying at eight.',why:'نحتاج إلى be بين will والفعل المنتهي بـ ing.'},
      'اسأل: هل أصف ما سيكون جاريًا في تلك اللحظة المستقبلية؟',
      [{text:'At 9 tomorrow, I ___ sleeping.',options:['will be','am','was'],answer:0,explain:'المستقبل المستمر يستخدم will be.'},{text:'They will be ___ at noon.',options:['travel','travels','travelling'],answer:2,explain:'بعد will be نستخدم verb-ing.'},{text:'Which phrase signals a future point?',options:['yesterday','this time tomorrow','last week'],answer:1,explain:'this time tomorrow يحدد وقتًا مستقبليًا.'}],'متوسط'),
    lesson('t-present-perfect-continuous','Present Perfect Continuous — المضارع التام المستمر','للنشاط الذي بدأ في الماضي وما زال مستمرًا أو نركز على مدته وأثره.','بدأت المذاكرة قبل ساعتين وما زلت تذاكر. تريد إبراز مدة النشاط واستمراره، فتستخدم هذا الزمن.','have / has been + verb-ing',
      ['استخدم have been مع I وyou وwe وthey.','استخدم has been مع he وshe وit.','أضف ing إلى الفعل.','تظهر معه for للمدة وsince لنقطة البداية غالبًا.'],
      [{en:'I have been studying for two hours.',ar:'أدرس منذ ساعتين.',focus:'have been studying'},{en:'She has been working since morning.',ar:'تعمل منذ الصباح.',focus:'has been working'},{en:'It has been raining all day.',ar:'تمطر طوال اليوم.',focus:'has been raining'}],
      {wrong:'He have been waiting.',right:'He has been waiting.',why:'مع he نستخدم has been.'},
      'for تليها مدة مثل two hours، وsince تليها نقطة بداية مثل Monday.',
      [{text:'She ___ been reading.',options:['have','has','is'],answer:1,explain:'مع she نستخدم has been.'},{text:'I have been ___ for an hour.',options:['wait','waited','waiting'],answer:2,explain:'بعد have been نستخدم verb-ing.'},{text:'Which one shows a duration?',options:['since Monday','for three hours','yesterday'],answer:1,explain:'for three hours تعبر عن مدة.'}],'متوسط'),
    lesson('t-past-perfect-continuous','Past Perfect Continuous — الماضي التام المستمر','للتعبير عن نشاط كان مستمرًا مدةً من الزمن قبل نقطة أو حدث آخر في الماضي.','وصلت إلى المدرسة الساعة الثامنة، وكنت قد بدأت المذاكرة قبل ذلك بساعة. نريد توضيح مدة النشاط قبل لحظة ماضية، لذلك نستخدم الماضي التام المستمر.','had been + verb-ing',
      ['استخدم had مع جميع الضمائر دون تغيير.','بعد had نضع been، ثم الفعل مع ing.','نستخدمه للتركيز على مدة نشاط استمر قبل حدث أو وقت ماضٍ.','for تذكر المدة، وsince تذكر نقطة البداية.'],
      [{en:'I had been studying for an hour when Ali called.',ar:'كنت أذاكر منذ ساعة عندما اتصل علي.',focus:'had been studying'},{en:'She was tired because she had been running.',ar:'كانت متعبة لأنها ظلت تركض قبل ذلك.',focus:'had been running'},{en:'They had been waiting since noon before the bus arrived.',ar:'كانوا ينتظرون منذ الظهر قبل وصول الحافلة.',focus:'had been waiting'}],
      {wrong:'He had been study for two hours.',right:'He had been studying for two hours.',why:'بعد had been نستخدم الفعل مع ing، وليس الفعل الأساسي.'},
      'فرّق بين had studied التي تركز على اكتمال الفعل، وhad been studying التي تبرز استمرار النشاط ومدته قبل نقطة ماضية.',
      [{text:'She had been ___ for an hour.',options:['read','reading','reads'],answer:1,explain:'بعد had been نستخدم الفعل مع ing: reading.'},{text:'They ___ been working before sunset.',options:['has','had','have'],answer:1,explain:'الماضي التام المستمر يستخدم had مع جميع الضمائر.'},{text:'Which phrase shows duration?',options:['for two hours','yesterday','tomorrow'],answer:0,explain:'for two hours تعني لمدة ساعتين.'}],'متوسط'),
    lesson('t-future-perfect','Future Perfect — المستقبل التام','للتعبير عن فعل سيكون قد اكتمل قبل وقت محدد في المستقبل.','لديك واجب وموعد تسليمه غدًا الساعة السادسة. إذا أنهيته قبل ذلك الموعد، تقول: سأكون قد أنهيته بحلول السادسة.','will have + past participle',
      ['استخدم will have مع جميع الضمائر.','بعد have نضع التصريف الثالث للفعل.','نستخدمه لنتيجة ستكون مكتملة قبل وقت مستقبلي محدد.','by وby the time تساعدان على تحديد الموعد الذي سيكون الفعل قد اكتمل قبله.'],
      [{en:'I will have finished my homework by six.',ar:'سأكون قد أنهيت واجبي بحلول السادسة.',focus:'will have finished'},{en:'She will have arrived before noon.',ar:'ستكون قد وصلت قبل الظهر.',focus:'will have arrived'},{en:'By next year, they will have built the school.',ar:'بحلول العام القادم، سيكونون قد بنوا المدرسة.',focus:'will have built'}],
      {wrong:'He will has finished.',right:'He will have finished.',why:'بعد will نستخدم have دائمًا، ولا نغيرها إلى has مع he.'},
      'اسأل نفسك: هل سيكون الفعل منتهيًا قبل موعد مستقبلي؟ إذا نعم، فقد يناسبه will have + التصريف الثالث.',
      [{text:'By Friday, we will have ___ the project.',options:['finish','finished','finishing'],answer:1,explain:'بعد will have نستخدم التصريف الثالث finished.'},{text:'She ___ have arrived by noon.',options:['will','has','is'],answer:0,explain:'صيغة المستقبل التام تبدأ بـ will have.'},{text:'Which phrase gives a future deadline?',options:['last night','by next week','every day'],answer:1,explain:'by next week تحدد موعدًا مستقبليًا سيكون الفعل قد اكتمل قبله.'}],'متوسط'),
    lesson('t-future-perfect-continuous','Future Perfect Continuous — المستقبل التام المستمر','لإبراز مدة استمرار نشاط حتى نقطة محددة في المستقبل.','تخيل أنه عند الساعة الخامسة غدًا ستكون قد أمضيت ثلاث ساعات في الدراسة. التركيز هنا على مدة النشاط حتى ذلك الوقت المستقبلي.','will have been + verb-ing',
      ['استخدم will have been مع جميع الضمائر.','أضف ing إلى الفعل بعد been.','اذكر غالبًا مدة النشاط باستخدام for.','نستخدمه عندما نركز على المدة التي سيكون النشاط قد استمرها حتى وقت مستقبلي.'],
      [{en:'By five, I will have been studying for three hours.',ar:'بحلول الخامسة، سأكون قد أمضيت ثلاث ساعات في الدراسة.',focus:'will have been studying'},{en:'Next month, she will have been working here for a year.',ar:'في الشهر القادم ستكون قد أمضت سنة تعمل هنا.',focus:'will have been working'},{en:'By noon, they will have been travelling for six hours.',ar:'بحلول الظهر، سيكونون قد أمضوا ست ساعات في السفر.',focus:'will have been travelling'}],
      {wrong:'I will have been study for hours.',right:'I will have been studying for hours.',why:'بعد will have been نستخدم الفعل مع ing.'},
      'المستقبل التام يركز على اكتمال النتيجة، أما المستقبل التام المستمر فيركز على مدة النشاط حتى وقت مستقبلي.',
      [{text:'By noon, he will have been ___ for hours.',options:['work','worked','working'],answer:2,explain:'بعد will have been نستخدم working.'},{text:'We ___ have been waiting for an hour.',options:['will','has','are'],answer:0,explain:'الصيغة تبدأ بـ will have been.'},{text:'This tense mainly emphasizes ___.',options:['a past habit','duration up to a future time','a completed past event'],answer:1,explain:'يركز على مدة نشاط حتى نقطة مستقبلية.'}],'متوسط')
  ];


  const tenseOrder = ['t-present-perfect-continuous','t-past-perfect','t-past-perfect-continuous','t-future-continuous','t-future-perfect','t-future-perfect-continuous'];
  tenses.sort((a, b) => tenseOrder.indexOf(a.slug) - tenseOrder.indexOf(b.slug));

  // شروح معمّقة مخصصة لكل درس؛ لا تُستبدل بشرح عام أو ترجمة حرفية للصيغة.
  const lessonGuides = {
    'g-subject-pronouns': {idea:'ضمير الفاعل هو الكلمة التي تحل محل اسم الشخص أو الشيء الذي يقوم بالفعل.',use:'استخدمه غالبًا قبل الفعل لتوضيح من يقوم به، وتجنب تكرار الاسم في الجمل المتتابعة.',build:['I = أنا، للشخص الذي يتكلم.','You = أنت أو أنتم، لمن تخاطبه.','He = هو لشخص مذكر، وShe = هي لشخص مؤنث، وIt لشيء أو حيوان بحسب السياق.','We = نحن عندما تكون أنت داخل المجموعة، وThey = هم/هن لمجموعة لا تشمل المتكلم.'],compare:'Ali is kind. He helps us. نستخدم He بدل تكرار Ali. أما Ali and I فتصبح We لأن المتكلم جزء من المجموعة.',watch:'لا تختَر الضمير بحسب قرب الاسم في الجملة فقط؛ اسأل: من المقصود؟ وهل هو المتكلم أم المخاطب أم شخص آخر؟'},
    'g-be-verb': {idea:'am / is / are أفعال تربط الفاعل بوصف أو اسم أو مكان، وتفيد معنى يكون/أكون في الحاضر.',use:'نحتاجها في جمل مثل أنا طالب، هي سعيدة، والكتب على الطاولة. لا نضع الصفة وحدها بعد الفاعل في هذا النوع من الجمل.',build:['I يأخذ am: I am ready.','He / She / It والاسم المفرد يأخذ is: Sara is happy.','You / We / They والجمع يأخذ are: They are at school.','للنفي نضيف not بعد الفعل، وللسؤال نقدّم am/is/are قبل الفاعل.'],compare:'She is tired وصف باستخدام be، لكن She studies فعل يصف نشاطًا؛ لا نضيف is قبل studies في المضارع البسيط.',watch:'لا تقل I is أو They is. احفظ ارتباط الضمير بالفعل، وانتبه أن you يأخذ are حتى لو كنت تخاطب شخصًا واحدًا.'},
    'g-present-simple': {idea:'المضارع البسيط يصف عادة متكررة أو حقيقة أو شيئًا ثابتًا، وليس بالضرورة شيئًا يحدث هذه اللحظة.',use:'مثل الروتين: أذهب للمدرسة كل يوم، أو حقيقة: الماء يغلي عند درجة حرارة معينة.',build:['مع I / You / We / They نستخدم الفعل الأساسي: play.','مع He / She / It أو اسم مفرد نضيف s غالبًا: plays.','نضيف es غالبًا بعد ch / sh / ss / x / z / o: watches, washes, goes.','إذا انتهى الفعل بحرف ساكن + y نحول y إلى ies: study → studies؛ أما play فتصبح plays لأن قبل y حرف علة.','في النفي نستخدم don’t / doesn’t ثم الفعل الأساسي. وفي السؤال نستخدم Do / Does ثم الفاعل والفعل الأساسي.'],compare:'I play / He plays. لكن He doesn’t play وDoes he play? لأن does تحمل علامة المفرد، فلا نكررها على الفعل.',watch:'الأسماء المفردة تعامل مثل he/she/it: My brother plays. ولا تضف s بعد does أو doesn’t. وhave تصبح has مع he/she/it.'},
    'g-present-continuous': {idea:'المضارع المستمر يصوّر فعلًا جارٍ الآن أو خلال فترة مؤقتة حول الوقت الحالي.',use:'إذا سألك شخص What are you doing? وأنت تدرس الآن، تقول I am studying.',build:['اختر am/is/are بحسب الفاعل: I am، he is، they are.','أضف ing إلى الفعل الأساسي: read → reading.','بعض الأفعال يتغير شكلها: make → making بحذف e، وrun → running بمضاعفة الحرف الأخير في حالات محددة.','للنفي ضع not بعد am/is/are، وللسؤال قدّم فعل be.'],compare:'I study every day عادة، أما I am studying now ففعل يحدث الآن.',watch:'لا تقل I studying؛ لا بد من am/is/are. وبعض أفعال الحالة مثل know وbelieve لا تستخدم غالبًا بصيغة continuous في معناها المعتاد.'},
    'g-past-simple': {idea:'الماضي البسيط يروي حدثًا بدأ وانتهى في الماضي.',use:'استخدمه مع وقت منتهٍ مثل yesterday أو last week أو عندما تسرد أحداثًا انتهت.',build:['الفعل المنتظم يأخذ ed غالبًا: clean → cleaned.','توجد تغييرات إملائية: study → studied، وstop → stopped.','الأفعال غير المنتظمة لها شكل محفوظ: go → went، see → saw.','للنفي والسؤال استخدم did، وبعدها ارجع للفعل الأساسي: didn’t go / Did you go?'],compare:'I visited my aunt yesterday حدث منتهٍ. أما I have visited London فيربط تجربة ماضية بالحاضر ولا يحدد وقتًا ماضيًا منتهيًا.',watch:'لا تجمع علامة الماضي مرتين: لا تقل didn’t went؛ did تحمل معنى الماضي والفعل بعدها أساسي.'},
    'g-past-continuous': {idea:'الماضي المستمر يصف فعلًا كان جاريًا في لحظة أو فترة محددة في الماضي.',use:'مثل: كنت أذاكر عندما اتصل صديقي. المذاكرة كانت مستمرة، والاتصال حدث أثناءها.',build:['was مع I / he / she / it والاسم المفرد.','were مع you / we / they والجمع.','بعد was/were نضع الفعل + ing.','when كثيرًا ما يقدم الحدث القصير، وwhile كثيرًا ما تربط حدثين مستمرين، لكن السياق هو الأساس.'],compare:'I studied at 8 تعني أنني درست في ذلك الوقت كحدث، أما I was studying at 8 فتركز على أن الدراسة كانت جارية حينها.',watch:'لا تستخدم was مع they أو were مع he. ولا تنس ing بعد was/were.'},
    'g-future-will': {idea:'will فعل مساعد للتحدث عن المستقبل، ويظهر كثيرًا في التوقعات والوعود والقرارات التي تتخذ لحظة الكلام.',use:'مثل أن تقرر الآن مساعدة شخص: I will help you، أو تتوقع: It will rain.',build:['ضع will بعد أي فاعل؛ لا تتغير مع الضمائر.','استخدم الفعل الأساسي بعدها دون s أو ed أو ing.','للنفي: will not أو won’t.','للسؤال: Will + subject + base verb?'],compare:'I will call قرار أو وعد، أما I am going to call فقد تبرز خطة أو نية موجودة مسبقًا.',watch:'لا تقل He will goes أو will to go؛ الصحيح He will go.'},
    'g-going-to': {idea:'be going to صيغة مستقبل تبرز خطة أو نية مقررة، أو توقعًا له دليل ظاهر.',use:'إذا خططت مسبقًا للمذاكرة الليلة، أو رأيت غيومًا كثيفة وتتوقع المطر.',build:['اختر am/is/are حسب الفاعل.','أضف going to بعد فعل be.','بعد to يأتي الفعل الأساسي دون s أو ing.','في النفي ضع not بعد am/is/are، وفي السؤال قدّم فعل be.'],compare:'I will study قد يكون قرارًا اتخذته الآن؛ I am going to study tonight توحي بخطة أو نية سابقة.',watch:'لا تحذف فعل be: ليس She going to؛ بل She is going to.'},
    'g-present-perfect': {idea:'المضارع التام يربط حدثًا ماضيًا بالحاضر؛ التركيز على التجربة أو النتيجة أو فترة لم تنتهِ.',use:'تجربة في الحياة دون تحديد وقت منتهٍ، أو نتيجة موجودة الآن، أو مدة بدأت في الماضي وما زالت مستمرة بحسب الفعل.',build:['have مع I/you/we/they، وhas مع he/she/it.','بعد have/has نستخدم التصريف الثالث، وليس الماضي البسيط دائمًا: go/went/gone.','ever للسؤال عن تجربة، never للنفي بمعنى لم يحدث قط، وalready/yet بحسب موقعها ومعناها.','for للمدة وsince لنقطة البداية في الاستخدامات المناسبة.'],compare:'I went yesterday ماضٍ محدد ومنتهٍ؛ I have been there تجربة دون وقت ماضٍ محدد.',watch:'لا تقل have saw؛ قل have seen. وتجنب عادةً yesterday أو last year مع المضارع التام عند الحديث عن وقت منتهٍ.'},
    'g-question-words': {idea:'أداة السؤال تحدد نوع المعلومة التي تريدها، ثم يأتي بعدها ترتيب السؤال المناسب.',use:'What للشيء أو المعلومة، Where للمكان، When للوقت، Why للسبب، Who للشخص، How للطريقة أو الحال.',build:['اختر الأداة حسب الإجابة التي تنتظرها.','إذا احتاج السؤال فعلًا مساعدًا، ضعه بعد أداة السؤال ثم الفاعل: Where do you live?','مع be نضع فعل be قبل الفاعل: Where are you?','Who قد يكون هو الفاعل نفسه، وعندها يختلف الترتيب: Who called you?'],compare:'Where do you live? يسأل عن المكان؛ When do you leave? يسأل عن الوقت. الأداة تتغير لكن بناء السؤال يبقى واضحًا.',watch:'لا تضع do آليًا في كل سؤال؛ إذا كان الفعل be هو الفعل الأساسي فلا نحتاج do: Where are you?'},
    'g-articles': {idea:'a وan تقدمان اسمًا مفردًا معدودًا غير محدد غالبًا، أما the فتشير إلى شيء محدد أو معروف.',use:'تقول I saw a dog عند ذكر كلب لأول مرة، ثم the dog إذا أصبح معروفًا أي كلب تقصد.',build:['a قبل صوت ساكن: a book، وan قبل صوت متحرك: an apple. العبرة بالصوت لا الحرف.','the مع شيء معروف من السياق أو محدد أو فريد بحسب المعنى.','a/an لا تأتيان عادةً مع الجمع أو الاسم غير المعدود.','قد لا نستخدم أداة مع الجمع أو غير المعدود عند الكلام العام: Books are useful.'],compare:'a university لأن البداية صوت /y/ ساكن، وan hour لأن h لا تُنطق ويبدأ الصوت بحركة.',watch:'لا تختَر a أو an من شكل أول حرف فقط؛ انطق الكلمة. ولا تقل an books.'},
    'g-time-prepositions': {idea:'حروف الجر الزمنية تحدد متى يقع الحدث، ولكل حرف نطاق شائع.',use:'at لنقطة زمنية دقيقة، on ليوم أو تاريخ، in لفترة أوسع.',build:['at 7:00 / at noon / at night في التعبير الشائع.','on Monday / on 5 May / on my birthday.','in July / in 2026 / in winter / in the morning.','بعض التعبيرات ثابتة ويجب تعلمها في سياقها.'],compare:'at 8:00 ساعة محددة، on Sunday يوم، in September شهر.',watch:'لا تقل at Monday أو in 7 o’clock. وتذكر وجود تعبيرات خاصة مثل at night وin the morning.'},
    'g-countable-uncountable': {idea:'الاسم المعدود يمكن عدّه كوحدات منفصلة، وغير المعدود يُعامل عادةً كمادة أو مفهوم لا نعده مباشرةً.',use:'book/books معدود؛ water وinformation غير معدودين في الاستخدام المعتاد.',build:['المعدود المفرد يمكن أن يأتي مع a/an، والجمع يأخذ s أو صيغة جمع خاصة.','غير المعدود لا يأخذ عادةً a/an ولا s للجمع: some water.','لعد غير المعدود استخدم وحدة: a glass of water / a piece of information.','اختيار much/many يعتمد على نوع الاسم لا على طول الكمية.'],compare:'many books لأن books معدود جمع؛ much water لأن water غير معدود.',watch:'لا تفترض أن كل ما يمكن عده بالعربية معدود بالطريقة نفسها بالإنجليزية؛ information وadvice غير معدودين غالبًا.'},
    'g-like-ing': {idea:'بعد like يمكن استخدام اسم أو فعل بصيغة ing للتحدث عن شيء تستمتع به أو تفضله.',use:'I like reading تعني أحب القراءة عمومًا، وI like music تستخدم اسمًا بعد like.',build:['ضع اسمًا بعد like: I like football.','أو ضع فعلًا بصيغة ing: I like swimming.','غيّر الفاعل دون تغيير like إلى likes مع he/she/it في المضارع البسيط.','يمكن استخدام like + to + base verb أيضًا، مع اختلافات دقيقة في التركيز بحسب السياق.'],compare:'I like swimming تركز على النشاط عمومًا؛ I want to swim تعبر عن رغبة أو نية.',watch:'لا تخلط بين like + ing وwant + to؛ لا تقل I like swim.'},
    'g-comparatives': {idea:'صيغة المقارنة تقارن شخصين أو شيئين في صفة واحدة.',use:'عندما تقول إن حقيبة أكبر من أخرى أو أن طريقًا أطول من طريق.',build:['الصفة القصيرة غالبًا تأخذ -er: tall → taller.','إذا انتهت الصفة بـ e نضيف r فقط: nice → nicer؛ وقد تتضاعف النهاية: big → bigger.','الصفات الطويلة غالبًا تستخدم more: more beautiful.','بعد المقارنة نستخدم than عند ذكر الطرف الثاني. وبعض الصفات شاذة: good → better، bad → worse.'],compare:'Ali is taller than Omar مقارنة بين اثنين؛ Ali is the tallest in the class تفضيل بين مجموعة.',watch:'لا تجمع more و-er: لا تقل more taller. وانتبه للتغييرات الإملائية والاستثناءات.'},
    'g-adverbs': {idea:'الظرف يصف كيف أو متى أو أين يحدث الفعل، بينما الصفة تصف الاسم.',use:'في She sings beautifully، الظرف يوضح طريقة الغناء.',build:['ابدأ بتحديد الكلمة التي تريد وصفها: اسم أم فعل؟','الصفة تصف الاسم: a careful driver.','الظرف يصف الفعل غالبًا: drives carefully.','كثير من الظروف تتكون بإضافة ly: quick → quickly، لكن توجد صور خاصة مثل fast وwell.'],compare:'He is careful: careful تصف He. He drives carefully: carefully تصف طريقة القيادة.',watch:'ليس كل ظرف ينتهي بـ ly، وبعض الكلمات المنتهية بـ ly صفات مثل friendly.'},
    'g-negatives-do-does': {idea:'نستخدم don’t وdoesn’t لنفي فعل في المضارع البسيط، وهما تحملان علامة الفاعل والزمن.',use:'للتعبير عن عادة لا تحدث: لا أشرب القهوة، أو هي لا تلعب التنس.',build:['don’t مع I/you/we/they.','doesn’t مع he/she/it والاسم المفرد.','بعد أداة النفي يأتي الفعل الأساسي دون s: doesn’t play.','الصيغة الكاملة do not وdoes not، والاختصار شائع في الكلام.'],compare:'She plays في الإثبات، لكنها She doesn’t play في النفي؛ انتقلت علامة المفرد من الفعل إلى does.',watch:'لا تقل doesn’t plays أو don’t likes. ولا تستخدم isn’t بدل don’t إلا إذا كان الفعل هو be.'},
    'g-present-simple-questions': {idea:'نكوّن سؤال المضارع البسيط بوضع Do أو Does قبل الفاعل، ثم الفعل الأساسي.',use:'للسؤال عن العادات والحقائق والتفضيلات: هل تلعب؟ هل تعمل أختك هنا؟',build:['Do مع I/you/we/they.','Does مع he/she/it والاسم المفرد.','بعد Do/Does يأتي الفاعل ثم الفعل الأساسي دون s.','مع أداة سؤال نضعها أولًا: Where do you live?'],compare:'You play football جملة خبرية؛ Do you play football? سؤال. وDoes she play? لا Does she plays?',watch:'بعد Does لا تضف s للفعل؛ علامة المفرد موجودة في Does.'},
    'g-there-is-are': {idea:'there is وthere are تخبران أن شيئًا موجود في مكان أو موقف.',use:'لوصف غرفة أو شارع: يوجد كتاب، توجد نافذتان.',build:['There is مع مفرد: There is a chair.','There are مع جمع: There are two chairs.','في النفي نضيف not بعد is/are.','في السؤال نبدأ بـ Is there أو Are there.'],compare:'There is a student مفرد؛ There are students جمع. الاختيار يعتمد على الاسم الذي يأتي بعدهما.',watch:'لا تدع there تخدعك؛ انظر إلى الاسم بعدها لتختار is أو are.'},
    'g-have-has': {idea:'have وhas يعبران غالبًا عن الملكية أو العلاقة أو بعض التجارب والتراكيب.',use:'للقول إن لديك كتابًا أو أن لدى أختك سيارة.',build:['have مع I/you/we/they.','has مع he/she/it والاسم المفرد.','في النفي والسؤال نستخدم do/does ثم have: Does she have...?','have قد تدخل في تراكيب أخرى مثل have breakfast، فيتحدد معناها من السياق.'],compare:'She has a car في الإثبات؛ Does she have a car? في السؤال. بعد does نرجع إلى have.',watch:'لا تقل Does he has؛ لأن does يتبعها الفعل الأساسي.'},
    'g-possessive-adjectives': {idea:'صفات الملكية توضح صاحب الشيء، وتأتي قبل الاسم الذي نملكه أو ننسبه لشخص.',use:'my book، her bag، their teacher.',build:['my = لي، your = لك/لكم.','his = له، her = لها، its = لشيء أو حيوان بحسب السياق.','our = لنا، their = لهم.','اختر الصفة بحسب المالك، ثم ضعها قبل الاسم.'],compare:'This is her book: her قبل اسم. This book is hers: hers ضمير ملكية ويأتي دون اسم بعده.',watch:'لا تخلط بين its للملكية وit’s اختصار it is أو it has.'},
    'g-object-pronouns': {idea:'ضمير المفعول يحل محل الشخص أو الشيء الذي يقع عليه الفعل أو يأتي بعد حرف جر.',use:'في I called him، المتكلم اتصل، وhim هو من تلقى الاتصال.',build:['I تصبح me، وhe تصبح him، وshe تصبح her.','we تصبح us، وthey تصبح them؛ وyou وit لا يتغير شكلهما.','يأتي غالبًا بعد الفعل أو حرف الجر: help me / with them.','ضمير الفاعل يقوم بالفعل، وضمير المفعول يتلقى الفعل.'],compare:'She helps me: She فاعل وme مفعول. لا نقول She helps I.',watch:'بعد حرف الجر مثل to / for / with نستخدم ضمير المفعول: for him، وليس for he.'},
    'g-some-any': {idea:'some وany تحددان كمية غير دقيقة، ويعتمد الاختيار على نوع الجملة والمعنى.',use:'some شائعة في الإثبات والعروض والطلبات؛ any شائعة في النفي والأسئلة.',build:['some مع جمع معدود أو اسم غير معدود: some apples / some water.','any في النفي: I don’t have any time.','any في الأسئلة العامة: Do you have any questions?','some قد تظهر في سؤال عرض أو طلب: Would you like some tea?'],compare:'I have some questions إثبات؛ I don’t have any questions نفي؛ Would you like some tea? عرض مهذب.',watch:'ليست القاعدة آلية 100%؛ افهم هل السؤال عرض/طلب أم سؤال مفتوح عن وجود شيء.'},
    'g-much-many-lot-of': {idea:'أدوات الكمية تختلف بحسب الاسم: معدود جمع أم غير معدود.',use:'للسؤال عن عدد الطلاب أو كمية الماء، أو وصف كمية كبيرة.',build:['many مع جمع معدود: many books.','much مع غير المعدود: much water.','a lot of تصلح للمعدود الجمع وغير المعدود: a lot of books/water.','How many للسؤال عن العدد، وHow much للسؤال عن الكمية أو السعر.'],compare:'How many apples? لأن apples معدود؛ How much milk? لأن milk غير معدود.',watch:'لا تقل much students. وفي الإثبات اليومي غالبًا a lot of أكثر طبيعية من much.'},
    'g-place-prepositions': {idea:'حروف جر المكان تصف العلاقة المكانية بين شيء وآخر.',use:'لتحديد مكان المفاتيح أو الحقيبة أو الكتاب.',build:['in = داخل مساحة أو وعاء.','on = على سطح أو مثبت على سطح بحسب السياق.','under = أسفل، next to = بجانب.','between = بين شيئين/طرفين، behind = خلف، in front of = أمام.'],compare:'The keys are in the bag داخل الحقيبة؛ The book is on the table فوق سطح الطاولة.',watch:'اختيار حرف الجر يصف العلاقة المقصودة؛ لا تترجم الحرف العربي حرفيًا دون النظر إلى الصورة.'},
    'g-can-cant': {idea:'can تعبر عن القدرة أو الإمكانية أو طلب الإذن، ولا تتغير بحسب الفاعل.',use:'للقول إنك تستطيع السباحة أو لطلب المساعدة.',build:['can تأتي بعد الفاعل وقبل الفعل الأساسي.','لا نضيف s أو to أو ing للفعل بعدها: can swim.','النفي cannot أو can’t.','للسؤال نقدم can: Can you help?'],compare:'She can swim، لا She cans swim. وفي السؤال Can she swim? لا نستخدم does.',watch:'can فعل مساعد؛ لا تجمعه مع do في السؤال ولا تضع to بعده.'},
    'g-must-should': {idea:'must تعبر عن إلزام أو ضرورة قوية، وshould تقدم نصيحة أو توصية.',use:'must لقاعدة واجبة، وshould لما هو مستحسن أو مفيد.',build:['must + الفعل الأساسي: You must stop.','should + الفعل الأساسي: You should rest.','mustn’t تعني ممنوع، أما shouldn’t فتعني لا يُنصح.','لا يتغير must أو should مع he/she/it.'],compare:'You must wear a seat belt إلزام؛ You should sleep early نصيحة.',watch:'لا تضع to أو s بعدهما: must go، should study.'},
    'g-imperatives': {idea:'صيغة الأمر تبدأ بالفعل الأساسي، والفاعل you مفهوم عادةً ولا نكتبه.',use:'للتعليمات والطلبات والإرشادات: افتح الكتاب، استمع جيدًا.',build:['ابدأ بالفعل الأساسي: Open your book.','أضف please لتلطيف الطلب.','للنهي استخدم Don’t + الفعل الأساسي.','يمكن إضافة مفعول أو مكان أو طريقة بعد الفعل.'],compare:'Open the door أمر مباشر؛ Please open the door طلب ألطف؛ Don’t open the door نهي.',watch:'لا تبدأ الأمر بـ to، ولا تستخدم doesn’t للنهي المباشر.'},
    'g-because-so': {idea:'because تقدم السبب، وso تقدم النتيجة.',use:'لشرح لماذا حدث شيء أو ماذا نتج عن سبب.',build:['بعد because نذكر السبب: I stayed home because I was sick.','بعد so نذكر النتيجة: I was sick, so I stayed home.','حدد أي الجزأين سبب وأيهما نتيجة قبل اختيار الأداة.','يمكن أن تأتي جملة because في البداية أيضًا مع فاصلة عند الحاجة.'],compare:'because = لأن، so = لذلك. الأولى تجيب لماذا؛ والثانية تقول ماذا حدث نتيجة لذلك.',watch:'لا تجمع because وso في تركيب واحد مثل Because I was tired, so I slept.'},
    'g-one-ones': {idea:'one وones يستبدلان اسمًا معدودًا سبق ذكره لتجنب تكراره.',use:'عندما تختار قلمًا من عدة أقلام: I like the blue one.',build:['one يحل محل اسم مفرد معدود.','ones يحل محل اسم جمع معدود.','يمكن أن تسبقهما صفة أو محدد: the red one / the small ones.','لا يستخدمان عادةً بدل اسم غير معدود مثل water.'],compare:'I need a pen. Do you have a blue one? كلمة one تعني pen ولا نكرر الاسم.',watch:'لا تستخدم one مع اسم جمع أو غير معدود؛ one chair / ones chairs خطأ.'},
    'g-too-enough': {idea:'too تعني أكثر من الحد المناسب غالبًا، وenough تعني الكمية أو الدرجة الكافية.',use:'لوصف أن الحقيبة ثقيلة جدًا أو أن الوقت كافٍ.',build:['too + adjective/adverb: too heavy.','adjective + enough: tall enough.','enough + noun: enough time.','too ... to قد تبين أن الزيادة تمنع الفعل: too tired to walk.'],compare:'The bag is too heavy تعني أثقل من المناسب؛ The bag is light enough تعني خفيفة بدرجة كافية.',watch:'موضع enough مهم: قبل الاسم، وبعد الصفة. لا تقل enough tall.'},
    'g-enjoy-ing': {idea:'الفعل enjoy يتبعه اسم أو فعل بصيغة ing للتعبير عن الاستمتاع بنشاط.',use:'I enjoy reading = أستمتع بالقراءة.',build:['بعد enjoy استخدم اسمًا أو verb-ing.','مع he/she/it في المضارع نقول enjoys.','يمكن إضافة مفعول أو ظرف بعد النشاط.','أفعال مثل avoid وfinish تتبعها ing غالبًا أيضًا، لكن لكل فعل نمطه.'],compare:'I enjoy swimming، لكن I want to swim؛ want يتبعها غالبًا to + base verb.',watch:'لا تقل enjoy to swim أو enjoy swim في هذا التركيب؛ قل enjoy swimming.'},
    'g-first-conditional': {idea:'الشرط الأول يتحدث عن احتمال واقعي أو ممكن في المستقبل ونتيجته.',use:'إذا درست، فستتحسن. النتيجة متوقعة إذا تحقق الشرط.',build:['جزء if يستخدم المضارع البسيط غالبًا.','جزء النتيجة يستخدم will + الفعل الأساسي غالبًا.','يمكن تقديم جملة if أو تأخيرها؛ إذا بدأت بها نضع فاصلة غالبًا.','لا نضع will عادةً مباشرة بعد if في هذا النمط الأساسي.'],compare:'If it rains, we will stay home احتمال مستقبلي؛ If it rained, we would stay home نمط افتراضي مختلف.',watch:'لا تقل If it will rain في الشرط الأول المعتاد؛ استخدم If it rains.'},
    'g-passive-voice': {idea:'المبني للمجهول يركز على الشيء الذي وقع عليه الفعل بدل التركيز على من قام به.',use:'عندما يكون الفاعل غير معروف أو غير مهم: The window was broken.',build:['ابدأ بالمفعول به في الجملة الأصلية ليصبح محور الجملة.','استخدم be بالزمن المناسب.','أضف التصريف الثالث للفعل: is made / was built.','يمكن إضافة by + الفاعل إذا كان ذكر من قام بالفعل مهمًا.'],compare:'Active: The chef cooked the meal. Passive: The meal was cooked by the chef.',watch:'لا يكفي وضع was/is وحدها؛ المبني للمجهول يحتاج be + past participle، ويتغير be بحسب الزمن.'},
    'g-relative-clauses': {idea:'جمل الوصل تضيف معلومة عن اسم سبق ذكره، وتربط الجمل بدل تكرار الاسم.',use:'The boy who lives next door is my friend.',build:['who للأشخاص غالبًا.','which للأشياء والحيوانات غالبًا.','that قد تستخدم للأشخاص أو الأشياء في جمل الوصل المحددة.','where للمكان وwhose للملكية.'],compare:'The girl is kind. She helps me. يمكن دمجهما: The girl who helps me is kind.',watch:'اختر أداة الوصل بحسب نوع الاسم ووظيفة المعلومة، وانتبه إلى أن بعض جمل الوصل لا تحتاج ضميرًا إذا كان مفعولًا في سياق مناسب.'},
    'g-reported-speech': {idea:'الكلام المنقول ينقل معنى كلام شخص دون وضع كلماته حرفيًا بين علامات اقتباس.',use:'قال أحمد إنه متعب: Ahmed said (that) he was tired.',build:['غيّر الضمائر بحسب المتكلم والمقصود.','بعد فعل نقل في الماضي قد يرجع الزمن خطوة: am → was، will → would.','تتغير كلمات الزمن والمكان بحسب وقت النقل: today → that day عند الحاجة.','إذا كانت الحقيقة ما زالت صحيحة أو في سياق خاص قد لا نرجع الزمن آليًا.'],compare:'Direct: “I am tired.” Reported: He said he was tired.',watch:'لا تغيّر كل كلمة آليًا؛ افهم من المتكلم، ومتى قيل الكلام، وهل المعلومة ما زالت صحيحة.'},
    'g-phrasal-verbs': {idea:'الفعل المركب يتكون من فعل مع حرف أو ظرف صغير، ويصبح له معنى اصطلاحي قد يختلف عن معنى كل كلمة منفردة.',use:'مثل turn on لتشغيل جهاز وgive up للاستسلام أو التوقف عن المحاولة.',build:['تعلم التعبير كوحدة واحدة مع مثال، لا تترجم كل جزء وحده.','بعض الأفعال المركبة قابلة للفصل: turn the light on / turn on the light.','إذا كان المفعول ضميرًا في الفعل القابل للفصل، يأتي غالبًا في الوسط: turn it on.','بعضها غير قابل للفصل: look after the child.'],compare:'look for = يبحث عن، look after = يعتني بـ؛ حرف الجر يغير المعنى.',watch:'لا تفترض أن كل phrasal verb يتبع نمطًا واحدًا؛ تعلم هل هو قابل للفصل أم لا.'},

    't-past-perfect-continuous': {idea:'يصف نشاطًا استمر مدةً قبل نقطة أو حدث آخر في الماضي، ويركز على مدة الاستمرار أو أثره.',use:'استخدمه عندما تريد توضيح كم من الوقت كان النشاط مستمرًا قبل وصول شخص أو وقوع حدث ماضٍ.',build:['had ثابتة مع جميع الضمائر.','بعدها been دائمًا.','بعد been نستخدم الفعل + ing: study → studying.','for + مدة، وsince + نقطة بداية.'],compare:'They had waited يركز على الانتظار كحدث أو نتيجة؛ They had been waiting يبرز استمرار الانتظار ومدته قبل الحدث الماضي.',watch:'لا تحذف been ولا تستخدم التصريف الثالث بعده؛ الصيغة had been + verb-ing.'},
    't-future-perfect': {idea:'يصف فعلًا سيكون قد اكتمل قبل موعد أو نقطة مستقبلية محددة.',use:'عندما تتحدث عن شيء تتوقع أن تنجزه قبل موعد قادم، مثل إنهاء الواجب بحلول السادسة.',build:['will have ثابتة مع جميع الضمائر.','بعد have نستخدم التصريف الثالث للفعل.','by + وقت مستقبلي يحدد الموعد النهائي غالبًا.','النفي: will not have + التصريف الثالث؛ والسؤال: Will + الفاعل + have...?'],compare:'I will finish at six قد يعني أنني سأنهيه في السادسة؛ I will have finished by six يعني أنني سأكون قد أنهيته قبل السادسة أو عندها.',watch:'لا تستخدم has بعد will حتى مع he/she/it؛ قل will have finished.'},
    't-future-perfect-continuous': {idea:'يركز على المدة التي سيكون نشاط ما قد استمرها عند الوصول إلى وقت مستقبلي.',use:'عندما تريد قول كم من الوقت ستكون قد أمضيته في نشاط بحلول موعد قادم.',build:['ابدأ بـ will have been مع جميع الضمائر.','أضف الفعل + ing بعد been.','استخدم for لذكر المدة غالبًا.','حدد نقطة مستقبلية مثل by noon أو by next year.'],compare:'will have completed تركز على اكتمال النتيجة؛ will have been working تركز على مدة العمل حتى الموعد.',watch:'تذكّر ترتيب الكلمات كاملًا: will ثم have ثم been ثم الفعل-ing؛ لا تحذف been.'},





    't-past-perfect': {idea:'يحدد حدثًا اكتمل قبل حدث أو نقطة أخرى في الماضي.',use:'عند ترتيب حدثين ماضيين وتوضيح أيهما وقع أولًا.',build:['had مع جميع الضمائر.','التصريف الثالث بعد had.','الحدث الأقدم غالبًا past perfect، والأحدث past simple.','قد تساعد before وafter وby the time على توضيح الترتيب.'],compare:'The train had left before I arrived: المغادرة أولًا، ثم الوصول.',watch:'لا تستخدم التصريف الثاني بعد had؛ قل had gone لا had went.'},


    't-future-continuous': {idea:'يصف فعلًا سيكون مستمرًا عند لحظة محددة في المستقبل.',use:'في مثل هذا الوقت غدًا سأكون أدرس؛ التركيز على النشاط الجاري في تلك اللحظة.',build:['will be ثابتة مع كل الضمائر.','أضف ing للفعل بعد be.','استخدم وقتًا مستقبليًا محددًا لتوضيح اللحظة.','يمكن استخدامه للسؤال بلطف عن خطط شخص: Will you be using the car?'],compare:'I will study at 8 قد يذكر فعلًا مستقبليًا؛ I will be studying at 8 يصور الفعل مستمرًا عند الثامنة.',watch:'لا تقل will studying؛ يجب be بين will والفعل ing.'},
    't-present-perfect-continuous': {idea:'يركز على نشاط بدأ في الماضي واستمر إلى الحاضر أو على مدته وآثاره.',use:'بدأت الدراسة قبل ساعتين وما زلت تدرس، أو انتهيت للتو وتظهر آثار النشاط.',build:['have been مع I/you/we/they، وhas been مع he/she/it.','أضف ing للفعل.','for تذكر مدة، وsince تذكر نقطة بداية.','قد يستمر النشاط حتى الآن أو يتوقف قريبًا مع بقاء أثره؛ السياق يوضح ذلك.'],compare:'I have read the book تركز على الإنجاز/النتيجة؛ I have been reading for two hours تركز على النشاط ومدته.',watch:'لا تخلط بين for وsince: for + مدة، since + نقطة بداية. ولا تنس been وing.'}
  };
  grammar.concat(tenses).forEach(item => { item.guide = lessonGuides[item.slug] || null; });
  const all = grammar.map(item => ({...item, type:'grammar'})).concat(tenses.map(item => ({...item, type:'tense'})));
  window.EnglishHeroLessons = { grammar, tenses, all };
})();